const MEMORY_EMAIL_VERIFICATION_EMAIL_PATTERN =
  /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$/;
const MEMORY_EMAIL_VERIFICATION_TOKEN_HASH_PATTERN = /^[0-9a-f]{64}$/;

function validateMemoryEmailVerificationEmail(email: unknown): asserts email is string {
  if (
    typeof email !== "string" ||
    email === "" ||
    email !== email.trim() ||
    email !== email.toLowerCase() ||
    email.length > 254 ||
    !MEMORY_EMAIL_VERIFICATION_EMAIL_PATTERN.test(email)
  ) {
    throw new TypeError("INVALID_EMAIL_VERIFICATION_EMAIL");
  }
}

function validateMemoryEmailVerificationPasswordHash(
  passwordHash: unknown
): asserts passwordHash is string {
  if (typeof passwordHash !== "string" || passwordHash === "") {
    throw new TypeError("INVALID_EMAIL_VERIFICATION_PASSWORD_HASH");
  }
}

function validateMemoryEmailVerificationTokenHash(
  tokenHash: unknown
): asserts tokenHash is string {
  if (
    typeof tokenHash !== "string" ||
    !MEMORY_EMAIL_VERIFICATION_TOKEN_HASH_PATTERN.test(tokenHash)
  ) {
    throw new TypeError("INVALID_EMAIL_VERIFICATION_TOKEN_HASH");
  }
}

function validateMemoryEmailVerificationExpiresAt(
  expiresAt: unknown
): asserts expiresAt is Date {
  if (
    !(expiresAt instanceof Date) ||
    Number.isNaN(expiresAt.getTime()) ||
    expiresAt.getTime() <= Date.now()
  ) {
    throw new TypeError("INVALID_EMAIL_VERIFICATION_EXPIRES_AT");
  }
}

function validateMemoryEmailVerificationNow(now: unknown): asserts now is Date {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError("INVALID_EMAIL_VERIFICATION_NOW");
  }
}

function validateMemoryPasswordResetEmail(email: unknown): asserts email is string {
  if (
    typeof email !== "string" ||
    email === "" ||
    email !== email.trim() ||
    email !== email.toLowerCase() ||
    email.length > 254 ||
    !MEMORY_EMAIL_VERIFICATION_EMAIL_PATTERN.test(email)
  ) {
    throw new TypeError("INVALID_PASSWORD_RESET_EMAIL");
  }
}

function validateMemoryPasswordResetTokenHash(
  tokenHash: unknown
): asserts tokenHash is string {
  if (
    typeof tokenHash !== "string" ||
    !MEMORY_EMAIL_VERIFICATION_TOKEN_HASH_PATTERN.test(tokenHash)
  ) {
    throw new TypeError("INVALID_PASSWORD_RESET_TOKEN_HASH");
  }
}

function validateMemoryPasswordResetPasswordHash(
  passwordHash: unknown
): asserts passwordHash is string {
  if (typeof passwordHash !== "string" || passwordHash === "") {
    throw new TypeError("INVALID_PASSWORD_RESET_PASSWORD_HASH");
  }
}

function validateMemoryPasswordResetNow(now: unknown): asserts now is Date {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError("INVALID_PASSWORD_RESET_NOW");
  }
}

function validateMemoryPasswordResetExpiresAt(
  expiresAt: unknown,
  now: Date
): asserts expiresAt is Date {
  if (
    !(expiresAt instanceof Date) ||
    Number.isNaN(expiresAt.getTime()) ||
    expiresAt.getTime() <= now.getTime()
  ) {
    throw new TypeError("INVALID_PASSWORD_RESET_EXPIRES_AT");
  }
}

