    it("changes the password through the Store CAS and invalidates all old JWTs without issuing a replacement", async () => {
      const store = createMemoryUserStore();
      const server = createTestServer({ store });
      const fixture = await createVerifiedUserAndTokenFixture({ server });
      const before = await store.findUserById(fixture.user.id);
      if (!before) throw new Error("TEST_USER_MISSING");
      const anotherOldJwt = createJwt(before.id, before.sessionVersion, "test-secret");
      const change = vi.spyOn(store, "changePasswordForUser");
      const recordLogin = vi.spyOn(store, "recordSuccessfulLogin");
      const response = await server.inject({
        method: "POST",
        url: "/auth/change-password",
        headers: { authorization: `Bearer ${fixture.token}` },
        payload: { currentPassword: fixture.password, newPassword: "replacement-password" }
      });
      const after = await store.findUserById(fixture.user.id);
      if (!after) throw new Error("TEST_CHANGED_USER_MISSING");
      const currentOldJwt = await server.inject({
        method: "GET",
        url: "/auth/me",
        headers: { authorization: `Bearer ${fixture.token}` }
      });
      const secondOldJwt = await server.inject({
        method: "GET",
        url: "/auth/me",
        headers: { authorization: `Bearer ${anotherOldJwt}` }
      });
      expect(recordLogin).not.toHaveBeenCalled();
      const oldPasswordLogin = await server.inject({
        method: "POST",
        url: "/auth/login",
        payload: { email: fixture.email, password: fixture.password }
      });
      const newPasswordLogin = await server.inject({
        method: "POST",
        url: "/auth/login",
        payload: { email: fixture.email, password: "replacement-password" }
      });

      expect(response.statusCode).toBe(200);
      expect(response.headers["cache-control"]).toBe("no-store");
      expect(response.json()).toEqual({ status: "PASSWORD_CHANGED" });
      expect(Object.keys(response.json())).toEqual(["status"]);
      expect(change).toHaveBeenCalledWith(expect.objectContaining({
        userId: before.id,
        expectedSessionVersion: before.sessionVersion,
        expectedPasswordHash: before.passwordHash,
        passwordHash: expect.any(String),
        now: expect.any(Date)
      }));
      const changedHash = change.mock.calls[0]?.[0].passwordHash;
      expect(await bcrypt.compare("replacement-password", changedHash ?? "")).toBe(true);
      expect(await bcrypt.compare(fixture.password, changedHash ?? "")).toBe(false);
      expect(currentOldJwt.statusCode).toBe(401);
      expect(secondOldJwt.statusCode).toBe(401);
      expect(after.sessionVersion).toBe(before.sessionVersion + 1);
      expect(oldPasswordLogin.statusCode).toBe(401);
      expect(newPasswordLogin.statusCode).toBe(200);
    });

