  it("registers an unverified user and sends a verification email", async () => {
    const store = createMemoryUserStore();
    const configuredServer = createTestServer({
      store,
      rateLimiter: {
        consume: async (_key, policy) => ({ allowed: true, limit: policy.limit, remaining: policy.limit - 1, retryAfterMs: policy.windowMs }),
        async close() {}
      }
    });
    const mailer = getTestEmailVerificationMailer(configuredServer);

    const response = await configuredServer.inject({
      method: "POST",
      url: "/auth/register",
      payload: {
        email: "person@example.com",
        password: "password123"
      }
    });

    const body = response.json();
    const storedUser = await store.findUserByEmail("person@example.com");
    const emailVerificationToken = storedUser
      ? store.getEmailVerificationTokenForTest(storedUser.id)
      : null;

    expect(response.statusCode).toBe(202);
    expect(response.headers["cache-control"]).toBe("no-store");
    expect(body).toEqual({
      status: "EMAIL_VERIFICATION_PENDING",
      message: "If the account can be verified, a verification email has been sent."
    });
    expect(body).not.toHaveProperty("token");
    expect(body).not.toHaveProperty("user");
    expect(storedUser?.passwordHash).not.toBe("password123");
    expect(storedUser).toMatchObject({
      emailVerifiedAt: null,
      lastLoginAt: null,
      sessionVersion: 0
    });
    expect(emailVerificationToken).toMatchObject({
      kind: UserTokenKind.EMAIL_VERIFICATION,
      usedAt: null
    });
    expect(mailer.calls).toHaveLength(1);
    expect(mailer.calls[0]?.to).toBe("person@example.com");
    expect(new URL(mailer.calls[0]?.verificationUrl ?? "").origin).toBe(
      "http://localhost:3000"
    );
  });

