  it("applies allowlist, denylist, ALL, and blocked-domain precedence", async () => {
    const store = createMemoryUserStore();
    const configuredServer = createTestServer({
      store,
      rateLimiter: {
        consume: async (_key, policy) => ({ allowed: true, limit: policy.limit, remaining: policy.limit - 1, retryAfterMs: policy.windowMs }),
        async close() {}
      }
    });
    const setPolicy = async (mode: string, allowed: string[], blocked: string[]) => {
      await store.updateSettings([
        { key: "registrationEmailPolicyEnabled", value: "true", type: "boolean" },
        { key: "registrationEmailPolicyMode", value: mode, type: "string" },
        { key: "registrationAllowedDomainsJson", value: JSON.stringify(allowed), type: "json" },
        { key: "registrationBlockedDomainsJson", value: JSON.stringify(blocked), type: "json" }
      ]);
    };
    await setPolicy("ALLOWLIST", ["gmail.com", "qq.com"], ["qq.com"]);
    for (const [email, status] of [
      ["one@gmail.com", 202], ["two@GMAIL.COM", 202], ["three@qq.com", 400],
      ["four@fake.gmail.com", 400], ["five@gmail.com.evil.example", 400]
    ] as const) {
      const response = await configuredServer.inject({ method: "POST", url: "/auth/register", payload: { email, password: "password123" } });
      expect(response.statusCode).toBe(status);
      if (status === 400) expect(response.json().code).toBe("EMAIL_DOMAIN_NOT_ALLOWED");
    }
    await setPolicy("DENYLIST", [], ["blocked.example"]);
    expect((await configuredServer.inject({ method: "POST", url: "/auth/register", payload: { email: "deny@normal.example", password: "password123" } })).statusCode).toBe(202);
    await setPolicy("ALL", [], ["blocked.example"]);
    expect((await configuredServer.inject({ method: "POST", url: "/auth/register", payload: { email: "all@blocked.example", password: "password123" } })).json().code).toBe("EMAIL_DOMAIN_NOT_ALLOWED");
  });

