    it("returns one invalid-token contract for malformed, unknown, expired, wrong-kind, used, and concurrent tokens", async () => {
      const invalidResponse = {
        code: "PASSWORD_RESET_TOKEN_INVALID",
        message: "Password reset link is invalid or expired."
      };

      const malformedServer = createTestServer();
      const malformedStore = testServerStores.get(malformedServer);
      if (!malformedStore) throw new Error("TEST_SERVER_STORE_MISSING");
      const consume = vi.spyOn(malformedStore, "consumePasswordResetToken");
      const malformed = await malformedServer.inject({
        method: "POST",
        url: "/auth/reset-password",
        payload: { token: "invalid", password: "replacement-password" }
      });
      const unknown = await malformedServer.inject({
        method: "POST",
        url: "/auth/reset-password",
        payload: {
          token: createPasswordResetToken().rawToken,
          password: "replacement-password"
        }
      });
      expect(malformed.statusCode).toBe(400);
      expect(malformed.headers["cache-control"]).toBe("no-store");
      expect(malformed.json()).toEqual(invalidResponse);
      expect(unknown.json()).toEqual(invalidResponse);
      expect(consume).toHaveBeenCalledTimes(1);

      const expiredStore = createMemoryUserStore();
      const expiredServer = createTestServer({ store: expiredStore });
      const expiredMailer = getTestPasswordResetMailer(expiredServer);
      const expiredUser = await createVerifiedUserAndTokenFixture({
        server: expiredServer,
        email: "s4c2-expired@example.test"
      });
      await expiredServer.inject({
        method: "POST",
        url: "/auth/request-password-reset",
        payload: { email: expiredUser.email }
      });
      const expiredRawToken = getRawPasswordResetToken(expiredMailer);
      const expiredToken = expiredStore.getPasswordResetTokenForTest(expiredUser.user.id);
      if (!expiredToken) throw new Error("TEST_PASSWORD_RESET_TOKEN_MISSING");
      expiredToken.expiresAt = new Date();
      const expired = await expiredServer.inject({
        method: "POST",
        url: "/auth/reset-password",
        payload: { token: expiredRawToken, password: "replacement-password" }
      });
      expect(expired.json()).toEqual(invalidResponse);

      const wrongKindStore = createMemoryUserStore();
      const wrongKindServer = createTestServer({ store: wrongKindStore });
      const wrongKindMailer = getTestPasswordResetMailer(wrongKindServer);
      const wrongKindUser = await createVerifiedUserAndTokenFixture({
        server: wrongKindServer,
        email: "s4c2-wrong-kind@example.test"
      });
      await wrongKindServer.inject({
        method: "POST",
        url: "/auth/request-password-reset",
        payload: { email: wrongKindUser.email }
      });
      const wrongKindRawToken = getRawPasswordResetToken(wrongKindMailer);
      const wrongKindToken = wrongKindStore.getPasswordResetTokenForTest(wrongKindUser.user.id);
      if (!wrongKindToken) throw new Error("TEST_PASSWORD_RESET_TOKEN_MISSING");
      wrongKindToken.kind = UserTokenKind.EMAIL_VERIFICATION;
      const wrongKind = await wrongKindServer.inject({
        method: "POST",
        url: "/auth/reset-password",
        payload: { token: wrongKindRawToken, password: "replacement-password" }
      });
      expect(wrongKind.json()).toEqual(invalidResponse);

      const concurrentStore = createMemoryUserStore();
      const concurrentServer = createTestServer({ store: concurrentStore });
      const concurrentMailer = getTestPasswordResetMailer(concurrentServer);
      const concurrentUser = await createVerifiedUserAndTokenFixture({
        server: concurrentServer,
        email: "s4c2-concurrent@example.test"
      });
      await concurrentServer.inject({
        method: "POST",
        url: "/auth/request-password-reset",
        payload: { email: concurrentUser.email }
      });
      const concurrentRawToken = getRawPasswordResetToken(concurrentMailer);
      const [first, second] = await Promise.all([
        concurrentServer.inject({
          method: "POST",
          url: "/auth/reset-password",
          payload: { token: concurrentRawToken, password: "replacement-password" }
        }),
        concurrentServer.inject({
          method: "POST",
          url: "/auth/reset-password",
          payload: { token: concurrentRawToken, password: "replacement-password" }
        })
      ]);
      expect([first.statusCode, second.statusCode].sort()).toEqual([200, 400]);
      expect(first.statusCode === 400 ? first.json() : second.json()).toEqual(invalidResponse);
    });

    it("reuses registration password validation without consuming the reset token", async () => {
      const store = createMemoryUserStore();
      const configuredServer = createTestServer({ store });
      const mailer = getTestPasswordResetMailer(configuredServer);
      const fixture = await createVerifiedUserAndTokenFixture({
        server: configuredServer,
        email: "s4c2-password-validation@example.test"
      });
      await configuredServer.inject({
        method: "POST",
        url: "/auth/request-password-reset",
        payload: { email: fixture.email }
      });
      const rawToken = getRawPasswordResetToken(mailer);

      const tooShort = await configuredServer.inject({
        method: "POST",
        url: "/auth/reset-password",
        payload: { token: rawToken, password: "short" }
      });
      const tooLong = await configuredServer.inject({
        method: "POST",
        url: "/auth/reset-password",
        payload: { token: rawToken, password: "密".repeat(25) }
      });
      const registrationInvalidType = await configuredServer.inject({
        method: "POST",
        url: "/auth/register",
        payload: { email: "s4c2-invalid-type@example.test", password: null }
      });
      const invalidType = await configuredServer.inject({
        method: "POST",
        url: "/auth/reset-password",
        payload: { token: rawToken, password: null }
      });

      expect(tooShort.statusCode).toBe(400);
      expect(tooShort.headers["cache-control"]).toBe("no-store");
      expect(tooShort.json()).toEqual({ message: "password must be at least 8 characters" });
      expect(tooLong.json()).toEqual({ message: "password must be at most 72 bytes" });
      expect(invalidType.json()).toEqual(registrationInvalidType.json());
      expect(store.getPasswordResetTokenForTest(fixture.user.id)?.usedAt).toBeNull();
      const valid = await configuredServer.inject({
        method: "POST",
        url: "/auth/reset-password",
        payload: { token: rawToken, password: "replacement-password" }
      });
      expect(valid.statusCode).toBe(200);
    });

