  it("uses each fallback route timeout and allows a first-route timeout to fallback", async () => {
    const store = createMemoryUserStore();
    const firstProvider = await store.createProviderAccount({
      name: "Chat Timeout Route One",
      providerType: "OPENAI_COMPATIBLE",
      baseUrl: "https://chat-timeout-one.example/v1",
      apiKey: "chat-timeout-one-key",
      capabilities: ["chat"],
      enabled: true,
      timeoutMs: 5
    });
    const secondProvider = await store.createProviderAccount({
      name: "Chat Timeout Route Two",
      providerType: "OPENAI_COMPATIBLE",
      baseUrl: "https://chat-timeout-two.example/v1",
      apiKey: "chat-timeout-two-key",
      capabilities: ["chat"],
      enabled: true,
      timeoutMs: 50
    });
    await store.createModelRoute({
      modelId: "model_gpt_test",
      providerId: firstProvider.id,
      upstreamModel: "timeout-route-one-model",
      priority: 1,
      enabled: true
    });
    await store.createModelRoute({
      modelId: "model_gpt_test",
      providerId: secondProvider.id,
      upstreamModel: "timeout-route-two-model",
      priority: 2,
      enabled: true
    });
    const requestedModels: string[] = [];
    let firstSignal: AbortSignal | undefined;
    let secondSignal: AbortSignal | undefined;
    const fetchImpl = vi.fn<typeof fetch>(async (_url, init) => {
      const body = JSON.parse(String(init?.body ?? "{}")) as { model?: string };
      requestedModels.push(body.model ?? "");
      if (body.model === "timeout-route-one-model") {
        firstSignal = init?.signal ?? undefined;
        return new Promise<Response>((_, reject) => {
          init?.signal?.addEventListener(
            "abort",
            () => reject(new DOMException("aborted", "AbortError")),
            { once: true }
          );
        });
      }

      secondSignal = init?.signal ?? undefined;
      await new Promise<void>((resolve) => setTimeout(resolve, 20));
      if (init?.signal?.aborted) {
        throw new DOMException("aborted", "AbortError");
      }
      return new Response(
        JSON.stringify({
          model: "timeout-route-two-model",
          choices: [{ message: { role: "assistant", content: "fallback OK" } }]
        }),
        { status: 200 }
      );
    });
    const configuredServer = createTestServer({ store, fetchImpl });

    const response = await configuredServer.inject({
      method: "POST",
      url: "/chat/completions",
      payload: {
        model: "gpt-test",
        messages: [{ role: "user", content: "timeout fallback" }]
      }
    });

    expect(response.statusCode).toBe(200);
    expect(response.json()).toMatchObject({
      model: "timeout-route-two-model",
      content: "fallback OK"
    });
    expect(requestedModels).toEqual([
      "timeout-route-one-model",
      "timeout-route-two-model"
    ]);
    expect(firstSignal?.aborted).toBe(true);
    expect(secondSignal?.aborted).toBe(false);
  });

