  it("creates, lists, reads, and deletes user-owned chat sessions", async () => {
    const { server: configuredServer, token } = await registerAndGetToken();
    const auth = { authorization: `Bearer ${token}` };

    const created = await configuredServer.inject({
      method: "POST",
      url: "/chat/sessions",
      headers: auth
    });
    const sessionId = created.json().session.id as string;

    const list = await configuredServer.inject({
      method: "GET",
      url: "/chat/sessions",
      headers: auth
    });
    const messages = await configuredServer.inject({
      method: "GET",
      url: `/chat/sessions/${sessionId}/messages`,
      headers: auth
    });
    const deleted = await configuredServer.inject({
      method: "DELETE",
      url: `/chat/sessions/${sessionId}`,
      headers: auth
    });
    const messagesAfterDelete = await configuredServer.inject({
      method: "GET",
      url: `/chat/sessions/${sessionId}/messages`,
      headers: auth
    });

    expect(created.statusCode).toBe(200);
    expect(created.json().session.title).toBe("新会话");
    expect(list.json().sessions).toHaveLength(1);
    expect(messages.statusCode).toBe(200);
    expect(messages.json().messages).toEqual([]);
    expect(deleted.statusCode).toBe(200);
    expect(deleted.headers["content-type"]).toContain("application/json");
    expect(deleted.json()).toEqual({ ok: true });
    expect(messagesAfterDelete.statusCode).toBe(404);
  });

