      for (let index = 0; index < 5; index += 1) {
        const response = await configuredServer.inject({ method: "POST", url: "/chat/completions", payload });
        expect(response.statusCode).toBe(200);
      }
      const blocked = await configuredServer.inject({ method: "POST", url: "/chat/completions", payload });

      expect(blocked.statusCode).toBe(429);
