    it("shares the canonical model bucket between model ID aliases and stream modes", async () => {
      const store = createMemoryUserStore();
      const aliasModel = await store.createModel({
        name: "Alias Guest Model",
        displayName: "Alias Guest Model",
        modelId: "provider-alias-model",
        provider: "SUB2API",
        capability: "chat",
        group: "free",
        tags: [],
        shortDescription: "",
        creditCost: 1,
        allowGuest: true,
        enabled: true,
        isRecommended: false,
        sortOrder: 3
      });
      await configureGuestRateLimits(store, {
        guestDailyLimit: "1000",
        guestBurstLimit: "20",
        guestPerModelHourlyLimit: "2"
      });
      const keys: string[] = [];
      const limiter: RateLimiter = {
        async consume(key, policy) {
          keys.push(key);
          const matching = keys.filter((item) => item === key).length;
          return {
            allowed: matching <= policy.limit,
            limit: policy.limit,
            remaining: Math.max(0, policy.limit - matching),
            retryAfterMs: policy.windowMs
          };
        },
        async close() {}
      };
      const configuredServer = createTestServer({ store, rateLimiter: limiter });

      const byModelId = await configuredServer.inject({
        method: "POST",
        url: "/chat/completions",
        payload: { ...payload, model: aliasModel.modelId }
      });
      const bySlug = await configuredServer.inject({
        method: "POST",
        url: "/chat/completions/stream",
        payload: { ...payload, model: aliasModel.slug }
      });
      const blocked = await configuredServer.inject({
        method: "POST",
        url: "/chat/completions",
        payload: { ...payload, model: aliasModel.slug }
      });
      const modelKeys = keys.filter((key) => key.startsWith("guest:chat:model:"));

      expect(byModelId.statusCode).toBe(200);
      expect(bySlug.statusCode).toBe(200);
      expect(blocked.json().code).toBe("GUEST_MODEL_RATE_LIMITED");
      expect(modelKeys).toEqual([
        `guest:chat:model:${aliasModel.id}:ip:127.0.0.1`,
        `guest:chat:model:${aliasModel.id}:ip:127.0.0.1`,
        `guest:chat:model:${aliasModel.id}:ip:127.0.0.1`
      ]);
      expect(modelKeys.every((key) => !key.includes("stream"))).toBe(true);
    });

