  it("validates feedback screenshot URLs before rate limiting and persistence", async () => {
    const store = createMemoryUserStore();
    const feedbackKeys: string[] = [];
    const baseLimiter = createInMemoryRateLimiter();
    const limiter: RateLimiter = {
      async consume(key, policy) {
        if (key.startsWith("feedback:")) feedbackKeys.push(key);
        return baseLimiter.consume(key, policy);
      },
      close: () => baseLimiter.close()
    };
    const createFeedback = vi.spyOn(store, "createFeedback");
    const configuredServer = createTestServer({ store, rateLimiter: limiter });
    const registered = await registerAndGetToken(configuredServer);

    const invalidValues: unknown[] = [
      "x".repeat(501),
      "java" + "script:alert(1)",
      "data:image/png;base64,AA==",
      "file:///tmp/screenshot.png",
      "blob:https://example.com/asset",
      "ftp://example.com/screenshot.png",
      "/relative/screenshot.png",
      "example.com/screenshot.png",
      "https://[invalid",
      "https://user:password@example.com/screenshot.png",
      42
    ];

    for (const screenshotUrl of invalidValues) {
      const response = await configuredServer.inject({
        method: "POST",
        url: "/feedback",
        headers: { authorization: `Bearer ${registered.token}` },
        payload: { content: "Invalid screenshot URL", type: "other", screenshotUrl }
      });

      expect(response.statusCode).toBe(400);
      expect(response.json()).toEqual({
        code: "FEEDBACK_SCREENSHOT_URL_INVALID",
        message: "截图链接格式不正确"
      });
    }

    expect(feedbackKeys).toEqual([]);
    expect(createFeedback).not.toHaveBeenCalled();

    const validValues: Array<unknown> = [
      undefined,
      null,
      "",
      "https://example.com/screenshot",
      "http://example.com/screenshot"
    ];

    for (const screenshotUrl of validValues) {
      const response = await configuredServer.inject({
        method: "POST",
        url: "/feedback",
        headers: { authorization: `Bearer ${registered.token}` },
        payload: { content: "Valid feedback", type: "other", screenshotUrl }
      });

      expect(response.statusCode).toBe(200);
    }

    expect(feedbackKeys).toHaveLength(validValues.length);
    expect(createFeedback).toHaveBeenCalledTimes(validValues.length);
    expect(createFeedback.mock.calls[3]?.[0].screenshotUrl).toBe(
      "https://example.com/screenshot"
    );
    expect(createFeedback.mock.calls[4]?.[0].screenshotUrl).toBe(
      "http://example.com/screenshot"
    );
  });

