  it("rate limit 429 message remains unchanged", async () => {
    const rl = createInMemoryRateLimiter();
    const configuredServer = createTestServer({ rateLimiter: rl });
    const compare = vi.spyOn(bcrypt, "compare").mockImplementation(
      (() => Promise.resolve(false)) as never
    );

    try {
      for (let i = 0; i < RATE_LIMITS.login.limit; i++) {
        await configuredServer.inject({
          method: "POST",
          url: "/auth/login",
          payload: { email: `rate-limit-${i}@example.com`, password: "wrong" }
        });
      }
      const rateLimited = await configuredServer.inject({
        method: "POST",
        url: "/auth/login",
        payload: { email: "rate-limit-blocked@example.com", password: "wrong" }
      });
      expect(rateLimited.statusCode).toBe(429);
      expect(rateLimited.json()).toMatchObject({
        code: "AUTH_LOGIN_RATE_LIMITED",
        message: "Too many login attempts."
      });
      const retryAfter = rateLimited.headers["retry-after"];
      expect(retryAfter).toEqual(expect.any(String));
      if (typeof retryAfter !== "string") {
        throw new Error("TEST_RETRY_AFTER_HEADER_MISSING");
      }
      const retryAfterSeconds = Number(retryAfter);
      expect(Number.isInteger(retryAfterSeconds)).toBe(true);
      expect(retryAfterSeconds).toBeGreaterThan(0);
      expect(retryAfterSeconds).toBeLessThanOrEqual(900);
      expect(rateLimited.headers["x-ratelimit-limit"]).toBe(String(RATE_LIMITS.login.limit));
      expect(rateLimited.headers["x-ratelimit-remaining"]).toBe("0");
      expect(rateLimited.json().retryAfterSeconds).toBe(retryAfterSeconds);
      expect(compare).toHaveBeenCalledTimes(RATE_LIMITS.login.limit);
    } finally {
      compare.mockRestore();
    }
  });

