  it("records fixed safe fields for provider failures during fallback", async () => {
    const messageCanaries = [
      "sk-log-message-canary",
      "Bearer log-bearer-canary",
      "Authorization: Bearer log-authorization-canary",
      "?api_key=log-query-canary"
    ];
    const nestedCause = new Error(
      `nested cause ${messageCanaries.join(" ")}`
    );
    const providerError = new Error(
      `AI provider request failed: 502 ${messageCanaries.join(" ")}`,
      { cause: nestedCause }
    );
    providerError.name = "ProviderTransportError";
    const stackCanary = "sk-log-stack-canary";
    providerError.stack = [
      providerError.name,
      `at provider-call ${stackCanary}`,
      "at upstream-request Bearer log-stack-bearer-canary",
      "Authorization: Bearer log-stack-authorization-canary",
      "?api_key=log-stack-query-canary"
    ].join("\n");

    const store = createMemoryUserStore();
    const fetchImpl = vi.fn<typeof fetch>(async (url) => {
      if (String(url).includes("log-safe-route-one")) {
        throw providerError;
      }

      return new Response(
        JSON.stringify({
          model: "log-safe-route-two-model",
          choices: [
            { message: { role: "assistant", content: "fallback success" } }
          ]
        }),
        { status: 200 }
      );
    });
    const configuredServer = createTestServer({ store, fetchImpl });
    const errorLog = vi
      .spyOn(configuredServer.log, "error")
      .mockImplementation(() => undefined);
    const firstProvider = await store.createProviderAccount({
      name: "Log Safe Route One",
      providerType: "OPENAI_COMPATIBLE",
      baseUrl: "https://log-safe-route-one.example/v1",
      apiKey: "log-safe-route-one-key",
      capabilities: ["chat"],
      enabled: true
    });
    const secondProvider = await store.createProviderAccount({
      name: "Log Safe Route Two",
      providerType: "OPENAI_COMPATIBLE",
      baseUrl: "https://log-safe-route-two.example/v1",
      apiKey: "log-safe-route-two-key",
      capabilities: ["chat"],
      enabled: true
    });
    const firstRoute = await store.createModelRoute({
      modelId: "model_gpt_test",
      providerId: firstProvider.id,
      upstreamModel: "log-safe-route-one-model",
      priority: 1,
      enabled: true
    });
    await store.createModelRoute({
      modelId: "model_gpt_test",
      providerId: secondProvider.id,
      upstreamModel: "log-safe-route-two-model",
      priority: 2,
      enabled: true
    });
    const { token, user } = await registerAndGetToken(configuredServer);

    try {
      const response = await configuredServer.inject({
        method: "POST",
        url: "/chat/completions",
        headers: { authorization: `Bearer ${token}` },
        payload: {
          model: "gpt-test",
          messages: [{ role: "user", content: "fallback logging" }]
        }
      });
      const usage = await configuredServer.inject({
        method: "GET",
        url: "/usage/me",
        headers: { authorization: `Bearer ${token}` }
      });
      const logCalls = errorLog.mock.calls as unknown[][];
      const routeFailureCall = logCalls.find(
        ([, message]) => message === "formal-chat model route failed"
      );
      const routeFailureFields = routeFailureCall?.[0];
      const serializedLogs = JSON.stringify(logCalls);
      const containsErrorObject = (
        value: unknown,
        seen = new Set<object>()
      ): boolean => {
        if (value instanceof Error) {
          return true;
        }
        if (value === null || typeof value !== "object") {
          return false;
        }
        if (seen.has(value)) {
          return false;
        }
        seen.add(value);
        return Array.isArray(value)
          ? value.some((item) => containsErrorObject(item, seen))
          : Object.values(value).some((item) =>
              containsErrorObject(item, seen)
            );
      };

      expect(response.statusCode).toBe(200);
      expect(response.json()).toMatchObject({
        model: "log-safe-route-two-model",
        content: "fallback success"
      });
      expect(fetchImpl).toHaveBeenCalledTimes(2);
      expect((await store.getQuota(user.id)).remainingCredits).toBe(19);
      expect(usage.json().logs[0]).toMatchObject({
        status: "SUCCESS",
        costCredits: 1,
        fallbackAttempts: 1
      });

      expect(routeFailureCall).toBeDefined();
      expect(routeFailureFields).toMatchObject({
        errorName: "ProviderTransportError",
        isProviderError: true,
        canonicalId: "gpt-test",
        providerId: firstProvider.id,
        providerName: firstProvider.name,
        upstreamModel: "log-safe-route-one-model",
        routeId: firstRoute.id,
        willFallback: true
      });
      expect(routeFailureFields).not.toHaveProperty("err");
      expect(routeFailureFields).not.toHaveProperty("error");
      expect(routeFailureFields).not.toHaveProperty("message");
      expect(routeFailureFields).not.toHaveProperty("stack");
      expect(routeFailureFields).not.toHaveProperty("cause");
      expect(logCalls.some((args) =>
        args.some((value) => containsErrorObject(value))
      )).toBe(false);
      for (const canary of [
        ...messageCanaries,
        stackCanary,
        "log-stack-bearer-canary",
        "log-stack-authorization-canary",
        "?api_key=log-stack-query-canary"
      ]) {
        expect(serializedLogs).not.toContain(canary);
      }
      expect(serializedLogs).not.toContain("Authorization");
      expect(serializedLogs).not.toContain("Bearer");
      expect(serializedLogs).not.toContain("api_key");
    } finally {
      errorLog.mockRestore();
    }
  });

