  it("lets admins manage persisted moderation routes without exposing account secrets", async () => {
    const store = createMemoryUserStore();
    const configuredServer = createTestServer({ store });
    const regular = await registerAndGetToken(configuredServer);
    const admin = await registerAdminAndGetToken(configuredServer, store);
    const providerAccount = await store.createProviderAccount({
      name: "Moderation Route Account",
      providerType: "OPENAI_COMPATIBLE",
      baseUrl: "https://moderation-route.example/v1",
      apiKey: "moderation-route-secret",
      capabilities: ["chat"],
      enabled: true,
      timeoutMs: 3000,
      configJson: {
        moderation: {
          requestFormat: "openai-moderation",
          endpointPath: "/v1/moderations",
          supportsText: true,
          supportsImage: true
        }
      }
    });

    const anonymous = await configuredServer.inject({
      method: "GET",
      url: "/admin/moderation"
    });
    const forbidden = await configuredServer.inject({
      method: "GET",
      url: "/admin/moderation",
      headers: { authorization: `Bearer ${regular.token}` }
    });
    const initial = await configuredServer.inject({
      method: "GET",
      url: "/admin/moderation",
      headers: { authorization: `Bearer ${admin.token}` }
    });
    const created = await configuredServer.inject({
      method: "POST",
      url: "/admin/moderation/routes",
      headers: { authorization: `Bearer ${admin.token}` },
      payload: {
        providerAccountId: providerAccount.id,
        upstreamModel: "omni-moderation-route",
        endpointPath: "/v1/moderations",
        priority: 1,
        timeoutMs: 3000,
        supportsText: true,
        supportsImage: true
      }
    });

    expect(anonymous.statusCode).toBe(401);
    expect(forbidden.statusCode).toBe(403);
    expect(initial.statusCode).toBe(200);
    expect(initial.json()).toEqual({
      settings: { version: 1, enabled: true, routes: [] }
    });
    expect(created.statusCode).toBe(200);
    const createdRoute = created.json().settings.routes[0] as {
      id: string;
      providerAccountId: string;
    };
    expect(createdRoute).toMatchObject({
      providerAccountId: providerAccount.id,
      providerAccountName: "Moderation Route Account",
      providerAccountEnabled: true,
      providerAccountCompatible: true
    });
    expect(JSON.stringify(created.json())).not.toContain(
      "moderation-route-secret"
    );

    const duplicatePriority = await configuredServer.inject({
      method: "POST",
      url: "/admin/moderation/routes",
      headers: { authorization: `Bearer ${admin.token}` },
      payload: {
        providerAccountId: providerAccount.id,
        priority: 1
      }
    });
    const unsafePath = await configuredServer.inject({
      method: "PUT",
      url: `/admin/moderation/routes/${createdRoute.id}`,
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { endpointPath: "/v1/%2e%2e/admin" }
    });
    const unsafeCreatePath = await configuredServer.inject({
      method: "POST",
      url: "/admin/moderation/routes",
      headers: { authorization: `Bearer ${admin.token}` },
      payload: {
        providerAccountId: providerAccount.id,
        endpointPath: "/v1/%2fadmin"
      }
    });
    const unsafeTimeout = await configuredServer.inject({
      method: "PUT",
      url: `/admin/moderation/routes/${createdRoute.id}`,
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { timeoutMs: 499 }
    });
    const unsafeTimeoutTooHigh = await configuredServer.inject({
      method: "PUT",
      url: `/admin/moderation/routes/${createdRoute.id}`,
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { timeoutMs: 10001 }
    });
    const missingAccount = await configuredServer.inject({
      method: "POST",
      url: "/admin/moderation/routes",
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { providerAccountId: "missing-provider-account" }
    });

    expect(duplicatePriority.statusCode).toBe(400);
    expect(duplicatePriority.json().code).toBe("MODERATION_PRIORITY_DUPLICATE");
    expect(unsafePath.statusCode).toBe(400);
    expect(unsafePath.json().code).toBe("MODERATION_ENDPOINT_PATH_INVALID");
    expect(unsafeCreatePath.statusCode).toBe(400);
    expect(unsafeCreatePath.json().code).toBe(
      "MODERATION_ENDPOINT_PATH_INVALID"
    );
    expect(unsafeTimeout.statusCode).toBe(400);
    expect(unsafeTimeout.json().code).toBe("IMAGE_MODERATION_TIMEOUT_INVALID");
    expect(unsafeTimeoutTooHigh.statusCode).toBe(400);
    expect(unsafeTimeoutTooHigh.json().code).toBe(
      "IMAGE_MODERATION_TIMEOUT_INVALID"
    );
    expect(missingAccount.statusCode).toBe(404);
    expect(missingAccount.json().code).toBe(
      "MODERATION_PROVIDER_ACCOUNT_NOT_FOUND"
    );

    const unchanged = await configuredServer.inject({
      method: "GET",
      url: "/admin/moderation",
      headers: { authorization: `Bearer ${admin.token}` }
    });
    expect(unchanged.json().settings.routes).toHaveLength(1);
    expect(unchanged.json().settings.routes[0]).toMatchObject({
      id: createdRoute.id,
      endpointPath: "/v1/moderations"
    });

    const updated = await configuredServer.inject({
      method: "PUT",
      url: `/admin/moderation/routes/${createdRoute.id}`,
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { supportsImage: false, upstreamModel: "updated-model" }
    });
    const disabled = await configuredServer.inject({
      method: "PUT",
      url: "/admin/moderation/settings",
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { enabled: false }
    });
    const deleted = await configuredServer.inject({
      method: "DELETE",
      url: `/admin/moderation/routes/${createdRoute.id}`,
      headers: { authorization: `Bearer ${admin.token}` }
    });

    expect(updated.statusCode).toBe(200);
    expect(updated.json().settings.routes[0]).toMatchObject({
      id: createdRoute.id,
      upstreamModel: "updated-model",
      supportsImage: false
    });
    expect(disabled.statusCode).toBe(200);
    expect(disabled.json().settings.enabled).toBe(false);
    expect(deleted.statusCode).toBe(200);
    expect(deleted.json().settings.routes).toEqual([]);
  });

  it("audits the canonical priority saved for created moderation routes", async () => {
    const store = createMemoryUserStore();
    const configuredServer = createTestServer({ store });
    const admin = await registerAdminAndGetToken(configuredServer, store);
    const providerAccount = await store.createProviderAccount({
      name: "Moderation Priority Account",
      providerType: "OPENAI_COMPATIBLE",
      baseUrl: "https://moderation-priority.example/v1",
      apiKey: "moderation-priority-secret",
      capabilities: ["chat"],
      enabled: true,
      timeoutMs: 3000,
      configJson: {
        moderation: { requestFormat: "openai-moderation" }
      }
    });

    const first = await configuredServer.inject({
      method: "POST",
      url: "/admin/moderation/routes",
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { providerAccountId: providerAccount.id, priority: 3 }
    });
    expect(first.statusCode).toBe(200);

    const automatic = await configuredServer.inject({
      method: "POST",
      url: "/admin/moderation/routes",
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { providerAccountId: providerAccount.id }
    });
    expect(automatic.statusCode).toBe(200);
    const automaticRoute = automatic.json().settings.routes.find(
      (route: { priority: number }) => route.priority === 4
    ) as { id: string; priority: number } | undefined;
    expect(automaticRoute).toMatchObject({ priority: 4 });

    const explicit = await configuredServer.inject({
      method: "POST",
      url: "/admin/moderation/routes",
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { providerAccountId: providerAccount.id, priority: 5 }
    });
    expect(explicit.statusCode).toBe(200);
    const explicitRoute = explicit.json().settings.routes.find(
      (route: { priority: number }) => route.priority === 5
    ) as { id: string; priority: number } | undefined;
    expect(explicitRoute).toMatchObject({ priority: 5 });

    const auditLogs = await store.listAdminAuditLogs();
    expect(
      auditLogs.find(
        (log) =>
          log.action === "CREATE_MODERATION_ROUTE" &&
          log.targetId === automaticRoute?.id
      )?.metadata?.priority
    ).toBe(4);
    expect(
      auditLogs.find(
        (log) =>
          log.action === "CREATE_MODERATION_ROUTE" &&
          log.targetId === explicitRoute?.id
      )?.metadata?.priority
    ).toBe(5);
  });

  it("tests one moderation route with fixed safe inputs and no failover", async () => {
    const store = createMemoryUserStore();
    const calls: string[] = [];
    const fetchImpl = vi.fn<typeof fetch>(async (url) => {
      calls.push(String(url));
      return new Response(
        JSON.stringify({
          results: [
            {
              flagged: false,
              categories: { sexual: false, "sexual/minors": false }
            }
          ],
          provider_secret: "must-not-be-returned"
        }),
        { status: 200 }
      );
    });
    const configuredServer = createTestServer({
      store,
      fetchImpl,
      env: {
        IMAGE_MODERATION_MODE: "enforce",
        IMAGE_MODERATION_API_KEY: "test-moderation-key"
      }
    });
    const admin = await registerAdminAndGetToken(configuredServer, store);
    const providerAccount = await store.createProviderAccount({
      name: "Fixed Test Account",
      providerType: "OPENAI_COMPATIBLE",
      baseUrl: "https://fixed-test.example/v1",
      apiKey: "fixed-test-secret",
      capabilities: ["chat"],
      enabled: true,
      timeoutMs: 3000,
      configJson: {
        moderation: { requestFormat: "openai-moderation" }
      }
    });
    const created = await configuredServer.inject({
      method: "POST",
      url: "/admin/moderation/routes",
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { providerAccountId: providerAccount.id, priority: 1 }
    });
    const routeId = created.json().settings.routes[0].id as string;

    const tested = await configuredServer.inject({
      method: "POST",
      url: `/admin/moderation/routes/${routeId}/test`,
      headers: { authorization: `Bearer ${admin.token}` }
    });
    const forbiddenInput = await configuredServer.inject({
      method: "POST",
      url: `/admin/moderation/routes/${routeId}/test`,
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { prompt: "user supplied prompt", url: "https://remote.invalid" }
    });

    expect(tested.statusCode).toBe(200);
    expect(tested.json()).toMatchObject({
      routeId,
      compatible: true,
      text: { supported: true, ok: true, decision: "allowed", errorType: null },
      image: { supported: true, ok: true, decision: "allowed", errorType: null }
    });
    expect(calls).toHaveLength(2);
    expect(JSON.stringify(tested.json())).not.toContain("fixed-test-secret");
    expect(JSON.stringify(tested.json())).not.toContain("provider_secret");
    expect(JSON.stringify(tested.json())).not.toContain("iVBORw0KGgo");

    fetchImpl.mockImplementation(async (url) => {
      calls.push(String(url));
      return new Response(
        JSON.stringify({
          results: [
            {
              flagged: true,
              categories: { sexual: true, "sexual/minors": false }
            }
          ]
        }),
        { status: 200 }
      );
    });
    const blockedSample = await configuredServer.inject({
      method: "POST",
      url: `/admin/moderation/routes/${routeId}/test`,
      headers: { authorization: `Bearer ${admin.token}` }
    });
    expect(blockedSample.json()).toMatchObject({
      routeId,
      compatible: true,
      text: { supported: true, ok: true, decision: "blocked" },
      image: { supported: true, ok: true, decision: "blocked" }
    });
    expect(calls).toHaveLength(4);

    fetchImpl.mockImplementation(async (url) => {
      calls.push(String(url));
      return new Response("not-json", { status: 200 });
    });
    const invalidResponse = await configuredServer.inject({
      method: "POST",
      url: `/admin/moderation/routes/${routeId}/test`,
      headers: { authorization: `Bearer ${admin.token}` }
    });
    expect(invalidResponse.json()).toMatchObject({
      compatible: false,
      text: {
        supported: true,
        ok: false,
        decision: null,
        errorType: "invalid_response"
      },
      image: {
        supported: true,
        ok: false,
        decision: null,
        errorType: "invalid_response"
      }
    });
    expect(calls).toHaveLength(6);

    const supportsTextOnly = await configuredServer.inject({
      method: "PUT",
      url: `/admin/moderation/routes/${routeId}`,
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { supportsImage: false }
    });
    expect(supportsTextOnly.statusCode).toBe(200);
    fetchImpl.mockImplementation(async (url) => {
      calls.push(String(url));
      return new Response(
        JSON.stringify({
          results: [{ flagged: false, categories: { sexual: false, "sexual/minors": false } }]
        }),
        { status: 200 }
      );
    });
    const textOnly = await configuredServer.inject({
      method: "POST",
      url: `/admin/moderation/routes/${routeId}/test`,
      headers: { authorization: `Bearer ${admin.token}` }
    });
    expect(textOnly.json()).toMatchObject({
      compatible: true,
      text: { supported: true, ok: true, decision: "allowed" },
      image: {
        supported: false,
        ok: false,
        decision: null,
        latencyMs: null,
        errorType: null
      }
    });
    expect(calls).toHaveLength(7);
    expect(forbiddenInput.statusCode).toBe(400);
    expect(forbiddenInput.json().code).toBe(
      "MODERATION_ROUTE_TEST_INPUT_FORBIDDEN"
    );
    expect(calls).toHaveLength(7);
  });

