  it("returns only explicitly allowed settings from GET /admin/settings", async () => {
    const store = createMemoryUserStore();
    const configuredServer = createTestServer({ store });
    const admin = await registerAdminAndGetToken(configuredServer, store);
    const ciphertextCanary = "pf-sec-1a1-ciphertext-canary:iv:tag:payload";
    const unknownKey = "futureCredentialSetting";
    const unknownValue = "pf-sec-1a1-unknown-secret-canary";

    await store.updateSettings([
      { key: "siteName", value: "Safe Admin Site", type: "string" },
      { key: "aiApiKey", value: ciphertextCanary, type: "string" },
      { key: "setupCompleted", value: "true", type: "boolean" },
      {
        key: "imageModerationSettings",
        value: JSON.stringify({ credential: "moderation-secret-canary" }),
        type: "json"
      },
      {
        key: "imageModerationCacheSettings",
        value: JSON.stringify({ credential: "cache-secret-canary" }),
        type: "json"
      },
      {
        key: "imageModerationCircuitBreakerSettings",
        value: JSON.stringify({ credential: "circuit-breaker-secret-canary" }),
        type: "json"
      },
      { key: unknownKey, value: unknownValue, type: "string" }
    ]);

    const response = await configuredServer.inject({
      method: "GET",
      url: "/admin/settings",
      headers: { authorization: `Bearer ${admin.token}` }
    });
    const serializedResponse = response.body;

    expect(response.statusCode).toBe(200);
    expect(response.json().settings).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          key: "siteName",
          value: "Safe Admin Site",
          type: "string"
        })
      ])
    );
    expect(serializedResponse).not.toContain("aiApiKey");
    expect(serializedResponse).not.toContain(ciphertextCanary);
    expect(serializedResponse).not.toContain("setupCompleted");
    expect(serializedResponse).not.toContain("imageModerationSettings");
    expect(serializedResponse).not.toContain("moderation-secret-canary");
    expect(serializedResponse).not.toContain("imageModerationCacheSettings");
    expect(serializedResponse).not.toContain("cache-secret-canary");
    expect(serializedResponse).not.toContain(
      "imageModerationCircuitBreakerSettings"
    );
    expect(serializedResponse).not.toContain("circuit-breaker-secret-canary");
    expect(serializedResponse).not.toContain(unknownKey);
    expect(serializedResponse).not.toContain(unknownValue);
  });

