  it("limits nickname updates to three per user per day and does not write after 429", async () => {
    const store = createMemoryUserStore();
    const writes = vi.fn();
    const updateUserProfile = store.updateUserProfile;
    store.updateUserProfile = async (userId, input) => {
      writes();
      return updateUserProfile?.(userId, input) ?? null;
    };
    const configuredServer = createTestServer({ store });
    const regular = await registerAndGetToken(configuredServer);

    for (const name of ["昵称一", "昵称二", "昵称三"]) {
      const response = await configuredServer.inject({
        method: "PATCH",
        url: "/account/profile",
        headers: { authorization: `Bearer ${regular.token}` },
        payload: { name }
      });
      expect(response.statusCode).toBe(200);
    }

    const blocked = await configuredServer.inject({
      method: "PATCH",
      url: "/account/profile",
      headers: { authorization: `Bearer ${regular.token}` },
      payload: { name: "昵称四" }
    });

    expect(blocked.statusCode).toBe(429);
    expect(blocked.json()).toMatchObject({
      code: "NICKNAME_UPDATE_RATE_LIMITED",
      message: "昵称修改过于频繁，请稍后再试",
      retryAfterSeconds: expect.any(Number)
    });
    expect(blocked.headers["retry-after"]).toBeTruthy();
    expect(blocked.headers["x-ratelimit-limit"]).toBe("3");
    expect(blocked.headers["x-ratelimit-remaining"]).toBe("0");
    expect(writes).toHaveBeenCalledTimes(3);
  });

