  it.each([
    {
      label: "PNG",
      mimeType: "image/png",
      dataUrl: "data:image/png;base64,iVBORw0KGgo="
    },
    {
      label: "JPEG",
      mimeType: "image/jpeg",
      dataUrl: "data:image/jpeg;base64,/9j/4AAQSkZJRgA="
    },
    {
      label: "WebP",
      mimeType: "image/webp",
      dataUrl:
        "data:image/webp;base64,UklGRhAAAABXRUJQVlA4IAQAAACdASoA"
    }
  ])(
    "S2-B2-B persists a real $label avatar and returns only the existing user contract",
    async ({ mimeType, dataUrl }) => {
      const store = createMemoryUserStore();
      const replace = vi.spyOn(store, "replaceUserAvatarReference");
      const assetDir = await mkdtemp(resolve(tmpdir(), "s2-b2-b-real-avatar-"));
      const configuredServer = createTestServer({
        store,
        env: { GENERATED_ASSETS_DIR: assetDir }
      });
      const regular = await registerAndGetToken(configuredServer);

      try {
        const response = await configuredServer.inject({
          method: "POST",
          url: "/account/avatar",
          headers: { authorization: `Bearer ${regular.token}` },
          payload: { dataUrl }
        });

        expect(response.statusCode).toBe(200);
        const body = response.json();
        expect(body).toEqual({
          user: {
            id: regular.user.id,
            email: regular.user.email,
            role: "USER",
            credits: 20,
            avatarUrl: expect.stringMatching(
              /^\/generated-assets\/images\/\d{4}\/\d{2}\/[0-9a-f-]+\.(?:png|jpg|webp)$/u
            )
          }
        });
        expect(body.user).not.toHaveProperty("avatarStorageObjectId");
        expect(body).not.toHaveProperty("storageObjectId");
        expect(body).not.toHaveProperty("objectKey");
        expect(body).not.toHaveProperty("sha256");
        expect(body).not.toHaveProperty("sizeBytes");
        expect(replace).toHaveBeenCalledWith({
          kind: "LOCAL_STORAGE_OBJECT",
          userId: regular.user.id,
          avatarUrl: body.user.avatarUrl,
          storageObjectId: expect.any(String)
        });
        await expect(
          readFile(
            resolve(
              assetDir,
              body.user.avatarUrl.replace(/^\/generated-assets\//u, "")
            )
          )
        ).resolves.toHaveLength(
          Buffer.from(dataUrl.slice(dataUrl.indexOf(",") + 1), "base64")
            .byteLength
        );
        const storedUser = await store.findUserById(regular.user.id);
        expect(storedUser).toMatchObject({
          avatarUrl: body.user.avatarUrl,
          avatarStorageObjectId: expect.any(String)
        });
        const referencedObject = storedUser?.avatarStorageObjectId
          ? await store.findStorageObjectForUser(
              regular.user.id,
              storedUser.avatarStorageObjectId
            )
          : null;
        expect(referencedObject).toMatchObject({
          mimeType,
          status: StorageObjectStatus.READY
        });
      } finally {
        await rm(assetDir, { recursive: true, force: true });
      }
    }
  );

  it("M7-B serves an uploaded avatar only through the authenticated private content route", async () => {
    const store = createMemoryUserStore();
    const assetDir = await mkdtemp(resolve(tmpdir(), "m7-avatar-content-"));
    const configuredServer = createTestServer({
      store,
      env: { GENERATED_ASSETS_DIR: assetDir }
    });
    const regular = await registerAndGetToken(configuredServer);
    const other = await registerWithEmail(configuredServer, "m7-avatar-other@example.test");
    const dataUrl = "data:image/png;base64,iVBORw0KGgo=";
    const expectedBytes = Buffer.from("iVBORw0KGgo=", "base64");

    try {
      const uploaded = await configuredServer.inject({
        method: "POST",
        url: "/account/avatar",
        headers: { authorization: `Bearer ${regular.token}` },
        payload: { dataUrl }
      });

      expect(uploaded.statusCode).toBe(200);
      const uploadedUser = uploaded.json().user as { avatarUrl: string };
      expect(uploadedUser.avatarUrl).toMatch(
        /^\/generated-assets\/images\/\d{4}\/\d{2}\/[0-9a-f-]+\.png$/u
      );

      const storedUser = await store.findUserById(regular.user.id);
      expect(storedUser).toMatchObject({
        avatarUrl: uploadedUser.avatarUrl,
        avatarStorageObjectId: expect.any(String)
      });

      const [me, overview, content, directPublic, anonymous, crossUser] = await Promise.all([
        configuredServer.inject({
          method: "GET",
          url: "/auth/me",
          headers: { authorization: `Bearer ${regular.token}` }
        }),
        configuredServer.inject({
          method: "GET",
          url: "/account/overview",
          headers: { authorization: `Bearer ${regular.token}` }
        }),
        configuredServer.inject({
          method: "GET",
          url: "/account/avatar/content",
          headers: { authorization: `Bearer ${regular.token}` }
        }),
        configuredServer.inject({ method: "GET", url: uploadedUser.avatarUrl }),
        configuredServer.inject({ method: "GET", url: "/account/avatar/content" }),
        configuredServer.inject({
          method: "GET",
          url: "/account/avatar/content",
          headers: { authorization: `Bearer ${other.token}` }
        })
      ]);

      expect(me.statusCode).toBe(200);
      expect(me.json().user.avatarUrl).toBe(uploadedUser.avatarUrl);
      expect(overview.statusCode).toBe(200);
      expect(overview.json().profile.avatarUrl).toBe(uploadedUser.avatarUrl);
      expect(content.statusCode).toBe(200);
      expect(content.rawPayload).toEqual(expectedBytes);
      expect(content.headers["content-type"]).toBe("image/png");
      expect(content.headers["cache-control"]).toBe("private, no-store");
      expect(content.headers.vary).toBe("Authorization");
      expect(content.body).not.toContain("images/");
      expect(directPublic.statusCode).toBe(404);
      expect(directPublic.json()).toEqual({ error: "asset not found" });
      expect(anonymous.statusCode).toBe(401);
      expect(crossUser.statusCode).toBe(404);
      expect(crossUser.json()).toEqual({ message: "avatar not found" });
    } finally {
      await configuredServer.close();
      await rm(assetDir, { recursive: true, force: true });
    }
  });

