  it("S2-B2-B serializes concurrent avatar replacements without deleting the final reference", async () => {
    const store = createMemoryUserStore();
    const avatarStorage = createTestAvatarStorageObjectService(store);
    const replacementResults: Awaited<
      ReturnType<ServerStore["replaceUserAvatarReference"]>
    >[] = [];
    const deletedIds: string[] = [];
    const replace = store.replaceUserAvatarReference;
    const markDeleted = store.markStorageObjectDeleted;
    store.replaceUserAvatarReference = async (input) => {
      const result = await replace(input);
      replacementResults.push(result);
      return result;
    };
    store.markStorageObjectDeleted = async (input) => {
      deletedIds.push(input.id);
      return markDeleted(input);
    };
    const configuredServer = createTestServer({
      store,
      avatarStorageObjectService: avatarStorage.service
    });
    const regular = await registerAndGetToken(configuredServer);
    const request = {
      method: "POST" as const,
      url: "/account/avatar",
      headers: { authorization: `Bearer ${regular.token}` },
      payload: { dataUrl: "data:image/png;base64,iVBORw0KGgo=" }
    };

    const [first, second] = await Promise.all([
      configuredServer.inject(request),
      configuredServer.inject(request)
    ]);

    expect(first.statusCode).toBe(200);
    expect(second.statusCode).toBe(200);
    expect(replacementResults).toHaveLength(2);
    const storedUser = await store.findUserById(regular.user.id);
    expect(storedUser?.avatarStorageObjectId).toEqual(expect.any(String));
    const replacedIds = replacementResults.flatMap((result) =>
      result.status === "UPDATED" && result.replacedStorageObjectId !== null
        ? [result.replacedStorageObjectId]
        : []
    );
    expect(deletedIds).toEqual(replacedIds);
    expect(deletedIds).not.toContain(storedUser?.avatarStorageObjectId);
    await expect(
      store.findStorageObjectForUser(
        regular.user.id,
        storedUser?.avatarStorageObjectId ?? ""
      )
    ).resolves.toMatchObject({
      status: StorageObjectStatus.READY
    });
  });

