  it("uses authenticated internal user IDs, isolates users, and does not consume for anonymous or invalid requests", async () => {
    const store = createMemoryUserStore();
    const keys: string[] = [];
    const baseLimiter = createInMemoryRateLimiter();
    const limiter: RateLimiter = {
      async consume(key, policy) {
        if (key.startsWith("profile:")) keys.push(key);
        return baseLimiter.consume(key, policy);
      },
      close: () => baseLimiter.close()
    };
    const configuredServer = createTestServer({ store, rateLimiter: limiter });
    const first = await registerWithEmail(configuredServer, "first@example.com");
    const second = await registerWithEmail(configuredServer, "second@example.com");

    const anonymous = await configuredServer.inject({
      method: "PATCH",
      url: "/account/profile",
      payload: { name: "未登录" }
    });
    const invalid = await configuredServer.inject({
      method: "PATCH",
      url: "/account/profile",
      headers: { authorization: `Bearer ${first.token}` },
      payload: { name: "\n\t" }
    });
    const forgedUserId = await configuredServer.inject({
      method: "PATCH",
      url: "/account/profile",
      headers: { authorization: `Bearer ${first.token}` },
      payload: { name: "真实昵称", userId: second.user.id }
    });
    const firstUpdate = await configuredServer.inject({
      method: "PATCH",
      url: "/account/profile",
      headers: { authorization: `Bearer ${first.token}` },
      payload: { name: "真实昵称" }
    });
    const secondUpdate = await configuredServer.inject({
      method: "PATCH",
      url: "/account/profile",
      headers: { authorization: `Bearer ${second.token}` },
      payload: { name: "另一昵称" }
    });

    expect(anonymous.statusCode).toBe(401);
    expect(invalid.statusCode).toBe(400);
    expect(invalid.json().code).toBe("INVALID_PROFILE_INPUT");
    expect(forgedUserId.statusCode).toBe(400);
    expect(firstUpdate.statusCode).toBe(200);
    expect(secondUpdate.statusCode).toBe(200);
    expect(keys).toEqual([
      `profile:nickname:user:${first.user.id}`,
      `profile:nickname:user:${second.user.id}`
    ]);
  });

