  it("returns paginated account activities with correct page, pageSize, total, and totalPages", async () => {
    const store = createMemoryUserStore();
    const configuredServer = createTestServer({ store });
    const admin = await registerAdminAndGetToken(configuredServer, store);
    const token = admin.token;
    const totalOrders = 20;

    const planIds: string[] = [];
    for (let i = 0; i < totalOrders; i++) {
      const plan = await store.createPlan({
        name: `Plan ${i}`,
        price: 100,
        credits: 1000,
        description: "Test",
        features: [],
        enabled: true,
        sortOrder: i
      });
      planIds.push(plan!.id);
    }

    for (const planId of planIds) {
      await configuredServer.inject({
        method: "POST",
        url: "/orders",
        headers: { authorization: `Bearer ${token}` },
        payload: { planId }
      });
    }

    const empty = await configuredServer.inject({
      method: "GET",
      url: "/account/activities"
    });
    expect(empty.statusCode).toBe(401);

    const headers = { authorization: `Bearer ${token}` };

    const defaultPage = await configuredServer.inject({
      method: "GET", url: "/account/activities", headers
    });
    expect(defaultPage.statusCode).toBe(200);
    expect(defaultPage.json().page).toBe(1);
    expect(defaultPage.json().pageSize).toBe(20);
    expect(defaultPage.json().total).toBe(totalOrders);
    expect(defaultPage.json().totalPages).toBe(1);
    expect(defaultPage.json().items.length).toBe(20);

    const pageSize10 = await configuredServer.inject({
      method: "GET", url: "/account/activities?pageSize=10", headers
    });
    expect(pageSize10.json().pageSize).toBe(10);
    expect(pageSize10.json().totalPages).toBe(2);
    expect(pageSize10.json().items.length).toBe(10);

    const pageSize50 = await configuredServer.inject({
      method: "GET", url: "/account/activities?pageSize=50", headers
    });
    expect(pageSize50.json().pageSize).toBe(50);
    expect(pageSize50.json().items.length).toBe(20);

    const pageSize100 = await configuredServer.inject({
      method: "GET", url: "/account/activities?pageSize=100", headers
    });
    expect(pageSize100.json().pageSize).toBe(100);
    expect(pageSize100.json().items.length).toBe(20);

    const page1 = await configuredServer.inject({
      method: "GET", url: "/account/activities?page=1&pageSize=10", headers
    });
    const page2 = await configuredServer.inject({
      method: "GET", url: "/account/activities?page=2&pageSize=10", headers
    });
    expect(page1.json().items.length).toBe(10);
    expect(page2.json().items.length).toBe(10);
    const page1Ids = page1.json().items.map((a: { id: string }) => a.id);
    const page2Ids = page2.json().items.map((a: { id: string }) => a.id);
    expect(page1Ids.filter((id: string) => page2Ids.includes(id))).toEqual([]);

    const invalidPage = await configuredServer.inject({
      method: "GET", url: "/account/activities?page=-1", headers
    });
    expect(invalidPage.statusCode).toBe(200);
    expect(invalidPage.json().page).toBe(1);

    const invalidPageSize = await configuredServer.inject({
      method: "GET", url: "/account/activities?pageSize=999", headers
    });
    expect(invalidPageSize.statusCode).toBe(200);
    expect(invalidPageSize.json().pageSize).toBe(100);

    const items = defaultPage.json().items as Array<{ createdAt: string }>;
    for (let i = 1; i < items.length; i++) {
      expect(new Date(items[i - 1]!.createdAt).getTime())
        .toBeGreaterThanOrEqual(new Date(items[i]!.createdAt).getTime());
    }
  });

