    expect(response.json().settings).toEqual(
      expect.objectContaining({
        siteName: "AI Aggregate",
        guestModeEnabled: true,
        registrationEnabled: true,
        maintenanceModeEnabled: false,
        defaultModel: "gpt-test"
      })
    );
