    expect(text).not.toContain("mysql://secret");
    expect(response.json().settings).not.toHaveProperty("guestRateLimitEnabled");
    expect(response.json().settings).not.toHaveProperty("guestDailyLimit");
    expect(response.json().settings).not.toHaveProperty("guestPerModelHourlyLimit");
    expect(response.json().settings).not.toHaveProperty("guestBurstLimit");
