  it("edits, disables, deletes links, filters public links, and writes audit logs", async () => {
    const store = createMemoryUserStore();
    const configuredServer = createTestServer({ store });
    const admin = await registerAdminAndGetToken(configuredServer, store);

    const createResult = await configuredServer.inject({
      method: "POST",
      url: "/admin/links",
      headers: {
        authorization: `Bearer ${admin.token}`,
        "content-type": "application/json"
      },
      payload: {
        title: "Original docs",
        url: "https://docs.example.test",
        category: "resource",
        enabled: true,
        sortOrder: 3
      }
    });
    const link = createResult.json().link as LinkEntry;

    const updateResult = await configuredServer.inject({
      method: "PATCH",
      url: `/admin/links/${link.id}`,
      headers: {
        authorization: `Bearer ${admin.token}`,
        "content-type": "application/json"
      },
      payload: {
        title: "Edited docs",
        url: "https://edited.example.test",
        description: "Updated description",
        category: "api",
        sortOrder: 1
      }
    });

    expect(updateResult.statusCode).toBe(200);
    expect(updateResult.json().link).toMatchObject({
      id: link.id,
      title: "Edited docs",
      url: "https://edited.example.test",
      description: "Updated description",
      category: "api",
      enabled: true,
      sortOrder: 1
    });

    const disableResult = await configuredServer.inject({
      method: "PATCH",
      url: `/admin/links/${link.id}`,
      headers: {
        authorization: `Bearer ${admin.token}`,
        "content-type": "application/json"
      },
      payload: {
        enabled: false
      }
    });

    expect(disableResult.statusCode).toBe(200);
    expect(disableResult.json().link.enabled).toBe(false);

    const hiddenResponse = await configuredServer.inject({
      method: "GET",
      url: "/links"
    });
    expect(
      (hiddenResponse.json().links as LinkEntry[]).some(
        (entry) => entry.id === link.id
      )
    ).toBe(false);

    const deleteResult = await configuredServer.inject({
      method: "DELETE",
      url: `/admin/links/${link.id}`,
      headers: {
        authorization: `Bearer ${admin.token}`
      }
    });

    expect(deleteResult.statusCode).toBe(200);
    expect(deleteResult.json()).toEqual({ ok: true });

    const adminLinksResult = await configuredServer.inject({
      method: "GET",
      url: "/admin/links",
      headers: {
        authorization: `Bearer ${admin.token}`
      }
    });
    expect(
      (adminLinksResult.json().links as LinkEntry[]).some(
        (entry) => entry.id === link.id
      )
    ).toBe(false);

    const auditResult = await configuredServer.inject({
      method: "GET",
      url: "/admin/audit-logs?limit=10",
      headers: {
        authorization: `Bearer ${admin.token}`
      }
    });
    const actions = (auditResult.json().logs as AdminAuditLogEntry[]).map(
      (entry) => entry.action
    );

    expect(actions).toContain("CREATE_LINK");
    expect(actions).toContain("UPDATE_LINK");
    expect(actions).toContain("DISABLE_LINK");
    expect(actions).toContain("DELETE_LINK");
  });

  it("archives feedback and hides archived feedback from the default admin list", async () => {
    const store = createMemoryUserStore();
    const configuredServer = createTestServer({ store });
    const admin = await registerAdminAndGetToken(configuredServer, store);

    await configuredServer.inject({
      method: "POST",
      url: "/feedback",
      headers: {
        authorization: `Bearer ${admin.token}`,
        "content-type": "application/json"
      },
      payload: {
        type: "feature",
        content: "Please add archive support"
      }
    });
    const beforeArchive = await configuredServer.inject({
      method: "GET",
      url: "/admin/feedbacks",
      headers: {
        authorization: `Bearer ${admin.token}`
      }
    });
    const feedback = (beforeArchive.json().feedbacks as FeedbackEntry[])[0];

    expect(beforeArchive.statusCode).toBe(200);
    expect(feedback).toBeDefined();
    if (!feedback) {
      throw new Error("Expected feedback in admin list before archive");
    }
    expect(feedback.archivedAt).toBeNull();

    const archiveResponse = await configuredServer.inject({
      method: "POST",
      url: `/admin/feedbacks/${feedback.id}/archive`,
      headers: {
        authorization: `Bearer ${admin.token}`
      }
    });

    expect(archiveResponse.statusCode).toBe(200);
    expect(archiveResponse.json().feedback.archivedAt).toEqual(
      expect.any(String)
    );

    const defaultList = await configuredServer.inject({
      method: "GET",
      url: "/admin/feedbacks",
      headers: {
        authorization: `Bearer ${admin.token}`
      }
    });
    const archivedList = await configuredServer.inject({
      method: "GET",
      url: "/admin/feedbacks?showArchived=true",
      headers: {
        authorization: `Bearer ${admin.token}`
      }
    });
    const auditResult = await configuredServer.inject({
      method: "GET",
      url: "/admin/audit-logs?limit=5",
      headers: {
        authorization: `Bearer ${admin.token}`
      }
    });

    expect(defaultList.json().feedbacks).toHaveLength(0);
    expect(archivedList.json().feedbacks).toHaveLength(1);
    expect(archivedList.json().feedbacks[0].archivedAt).toEqual(
      expect.any(String)
    );
    expect(
      (auditResult.json().logs as AdminAuditLogEntry[]).some(
        (entry) => entry.action === "ARCHIVE_FEEDBACK"
      )
    ).toBe(true);
  });

