  it("returns bounded safe admin operations visibility without Store writes", async () => {
    const store = createMemoryUserStore();
    const globalBudgetStore = {
      async consumeGlobalBudget() {
        return { status: "consumed" as const };
      },
      async listAdminBudgetPeriods() {
        return [
          {
            scope: "image_generation" as const,
            periodType: "DAILY" as const,
            periodKey: "2026-06-11",
            limit: 100,
            used: 20,
            remaining: 80,
            status: "NORMAL" as const,
            updatedAt: "2026-06-11T11:00:00.000Z"
          },
          {
            scope: "chat_completion" as const,
            periodType: "DAILY" as const,
            periodKey: "2026-06-11",
            limit: 10,
            used: 8,
            remaining: 2,
            status: "NEAR_LIMIT" as const,
            updatedAt: "2026-06-11T11:01:00.000Z"
          },
          {
            scope: "admin_provider_test" as const,
            periodType: "DAILY" as const,
            periodKey: "2026-06-11",
            limit: 5,
            used: 9,
            remaining: 0,
            status: "EXHAUSTED" as const,
            updatedAt: "2026-06-11T11:02:00.000Z"
          }
        ];
      }
    };
    const configuredServer = createTestServer({
      store,
      globalBudgetStore
    });
    const admin = await registerAdminAndGetToken(configuredServer, store);
    const regularUser = await store.createUser({
      email: "operations-target@example.com",
      passwordHash: "hash"
    });

    for (let index = 0; index < 51; index += 1) {
      await store.createAiTask({
        userId: regularUser.id,
        type: "image",
        modelId: "gpt-test",
        prompt: `bounded prompt ${index}`,
        input: { index }
      });
    }

    const unchargedFailedTask = await store.createAiTask({
      userId: regularUser.id,
      type: "image",
      modelId: "gpt-test",
      prompt: "UNCHARGED_PROMPT_SECRET",
      input: { imagePath: "/private/uncharged.png" }
    });
    await store.failAiTask(
      unchargedFailedTask.id,
      "Provider raw failure that must stay private"
    );

    const chargedAndFailed = await store.createImageTaskWithReservation({
      userId: admin.user.id,
      amountCredits: 2,
      expiresAt: new Date("2026-06-12T00:00:00.000Z"),
      task: {
        type: "image",
        modelId: "gpt-test",
        prompt: "PROMPT_SECRET https://private.example/upload.png",
        input: {
          negativePrompt: "NEGATIVE_PROMPT_SECRET",
          imagePath: "/private/user/upload.png",
          authorization: "Bearer raw-token"
        }
      }
    });
    expect(chargedAndFailed.ok).toBe(true);
    if (!chargedAndFailed.ok) {
      throw new Error("TEST_CHARGED_TASK_NOT_CREATED");
    }
    await expect(
      store.settleCreditReservation(chargedAndFailed.reservation.id)
    ).resolves.toEqual({ status: "UPDATED" });
    const failed = await store.failAiTask(
      chargedAndFailed.task.id,
      "Provider 500 https://provider.example/v1/images raw-provider-error stack"
    );
    expect(failed?.status).toBe("failed");

    await store.createAuditLog({
      adminUserId: admin.user.id,
      adminEmail: admin.user.email,
      action: "UPDATE_USER_QUOTA",
      targetType: "User",
      targetId: regularUser.id,
      summary: "sensitive@example.com raw audit text",
      metadata: {
        deltaCredits: 2,
        secret: "do-not-return"
      }
    });

    const createTask = vi.spyOn(store, "createAiTask");
    const createAudit = vi.spyOn(store, "createAuditLog");
    const overview = await configuredServer.inject({
      method: "GET",
      url: "/admin/overview",
      headers: { authorization: `Bearer ${admin.token}` }
    });
    const body = overview.json();

    expect(overview.statusCode).toBe(200);
    expect(overview.headers["cache-control"]).toBe("no-store");
    expect(body.operations.recentTasks).toHaveLength(50);
    expect(body.operations.recentTasks[0]).toEqual({
      taskId: chargedAndFailed.task.id,
      userId: admin.user.id,
      type: "image",
      status: "failed",
      modelId: "gpt-test",
      modelLabel: "GPT Test",
      providerLabel: null,
      routeId: null,
      createdAt: expect.any(String),
      updatedAt: expect.any(String),
      safeErrorClass: "CHARGED_AND_FAILED",
      chargeStatus: "SETTLED",
      creditReleaseStatus: "NOT_RELEASED",
      refundStatus: "UNKNOWN",
      costRecorded: false
    });
    expect(body.operations.recentTasks.every((task: { taskId: string }) =>
      typeof task.taskId === "string"
    )).toBe(true);
    expect(
      body.operations.recentTasks.find(
        (task: { taskId: string }) => task.taskId === unchargedFailedTask.id
      )
    ).toMatchObject({
      safeErrorClass: "TASK_FAILED",
      chargeStatus: "UNKNOWN",
      creditReleaseStatus: "UNKNOWN",
      refundStatus: "UNKNOWN"
    });
    expect(body.operations.manualCompensations).toEqual([
      {
        auditId: expect.any(String),
        targetUserId: regularUser.id,
        action: "UPDATE_USER_QUOTA",
        createdAt: expect.any(String),
        creditChangeStatus: "RECORDED",
        creditDelta: 2
      }
    ]);
    expect(body.operations.budgets).toEqual(
      await globalBudgetStore.listAdminBudgetPeriods()
    );
    const operationsJson = JSON.stringify(body.operations);
    for (const forbidden of [
      "PROMPT_SECRET",
      "NEGATIVE_PROMPT_SECRET",
      "UNCHARGED_PROMPT_SECRET",
      "/private/user/upload.png",
      "raw-token",
      "raw-provider-error",
      "sensitive@example.com",
      "do-not-return"
    ]) {
      expect(operationsJson).not.toContain(forbidden);
    }
    expect(createTask).not.toHaveBeenCalled();
    expect(createAudit).not.toHaveBeenCalled();
  });

