  it("returns a safe transaction error without a fallback financial audit", async () => {
    const store = createMemoryUserStore();
    const configuredServer = createTestServer({ store });
    const admin = await registerAdminAndGetToken(configuredServer, store);
    const createAudit = vi.spyOn(store, "createAuditLog");
    const quotaTransaction = vi
      .spyOn(store, "adjustUserQuotaWithAudit")
      .mockRejectedValue(new Error("FIXTURE_FINANCIAL_FAILURE"));

    const quotaResponse = await configuredServer.inject({
      method: "PATCH",
      url: `/admin/users/${admin.user.id}/quota`,
      headers: { authorization: `Bearer ${admin.token}` },
      payload: { remainingCredits: 30 }
    });

    expect(quotaResponse.statusCode).toBe(500);
    expect(quotaResponse.json()).toEqual({ message: "服务暂时不可用，请稍后再试" });
    expect(quotaResponse.body).not.toContain("FIXTURE_FINANCIAL_FAILURE");
    expect(createAudit).not.toHaveBeenCalled();
    quotaTransaction.mockRestore();
    createAudit.mockRestore();
  });

