  it("resolves canonical slugs before unique legacy IDs and rejects ambiguity", async () => {
    const store = createMemoryUserStore();
    const slugMatch: AiModelSummary = {
      id: "model_slug_match",
      name: "Slug Match",
      slug: "image2",
      provider: "SUB2API",
      modelId: "legacy-slug-match",
      capability: "chat",
      displaySurfaces: ["chat"],
      enabled: true,
      maxReferenceImages: 1,
      creditCost: 1,
      allowGuest: true,
      sortOrder: 20,
      group: "chat",
      tags: [],
      shortDescription: "",
      isRecommended: false
    };
    const legacyMatch: AiModelSummary = {
      ...slugMatch,
      id: "model_legacy_match",
      name: "Legacy Match",
      slug: "legacy-match",
      modelId: "image2"
    };
    const ambiguousA: AiModelSummary = {
      ...slugMatch,
      id: "model_ambiguous_a",
      slug: "ambiguous-a",
      modelId: "ambiguous-legacy"
    };
    const ambiguousB: AiModelSummary = {
      ...slugMatch,
      id: "model_ambiguous_b",
      slug: "ambiguous-b",
      modelId: "ambiguous-legacy"
    };
    store.seedModelForTest(slugMatch);
    store.seedModelForTest(legacyMatch);
    store.seedModelForTest(ambiguousA);
    store.seedModelForTest(ambiguousB);

    await expect(store.findModelByModelId("image2")).resolves.toMatchObject({
      id: "model_slug_match"
    });
    await expect(
      store.findModelByModelId("legacy-slug-match")
    ).resolves.toMatchObject({ id: "model_slug_match" });
    await expect(store.findModelByModelId("ambiguous-legacy")).rejects.toMatchObject({
      code: "MODEL_IDENTITY_CONFLICT",
      kind: "AMBIGUOUS_LEGACY_MODEL_ID"
    });
  });

