  describe("POST /orders/:id/cancel", () => {
    async function createCancellableOrderFixture() {
      const store = createMemoryUserStore();
      const server = createTestServer({ store });
      const { token, user } = await registerAndGetToken(server);
      const plan = await store.createPlan({
        name: "User cancel plan",
        price: 2900,
        credits: 300,
        description: "User-owned cancellation fixture",
        features: [],
        enabled: true,
        sortOrder: 1
      });
      const order = await store.createOrder({
        userId: user.id,
        planId: plan.id
      });

      if (!order) {
        throw new Error("TEST_CANCEL_ORDER_MISSING");
      }

      return { store, server, token, user, order };
    }

    it("lets the owner cancel PENDING idempotently", async () => {
      const context = await createCancellableOrderFixture();

      const first = await context.server.inject({
        method: "POST",
        url: `/orders/${context.order.id}/cancel`,
        headers: { authorization: `Bearer ${context.token}` }
      });
      const second = await context.server.inject({
        method: "POST",
        url: `/orders/${context.order.id}/cancel`,
        headers: { authorization: `Bearer ${context.token}` }
      });
      const activities = await context.server.inject({
        method: "GET",
        url: "/account/activities",
        headers: { authorization: `Bearer ${context.token}` }
      });
      const cancelledActivity = activities.json().items.find(
        (activity: { id: string }) => activity.id === `order:${context.order.id}`
      );

      expect(first.statusCode).toBe(200);
      expect(first.json()).toMatchObject({
        order: { id: context.order.id, status: "CANCELLED", paidAt: null },
        alreadyCancelled: false
      });
      expect(second.statusCode).toBe(200);
      expect(second.json()).toMatchObject({
        order: { id: context.order.id, status: "CANCELLED", paidAt: null },
        alreadyCancelled: true
      });
      expect(activities.statusCode).toBe(200);
      expect(cancelledActivity).toMatchObject({
        kind: "ORDER",
        status: "CANCELLED",
        completedAt: null
      });
    });

    it("rejects PAID and other users with non-disclosing responses", async () => {
      const paidContext = await createCancellableOrderFixture();
      const admin = await registerAdminAndGetToken(
        paidContext.server,
        paidContext.store
      );
      await paidContext.store.markOrderPaidByAdmin({
        orderId: paidContext.order.id,
        adminUserId: admin.user.id,
        adminEmail: admin.user.email
      });

      const paid = await paidContext.server.inject({
        method: "POST",
        url: `/orders/${paidContext.order.id}/cancel`,
        headers: { authorization: `Bearer ${paidContext.token}` }
      });

      const ownedContext = await createCancellableOrderFixture();
      const other = await registerWithEmail(
        ownedContext.server,
        "cancel-other-user@example.com"
      );
      const notOwned = await ownedContext.server.inject({
        method: "POST",
        url: `/orders/${ownedContext.order.id}/cancel`,
        headers: { authorization: `Bearer ${other.token}` }
      });
      const missing = await ownedContext.server.inject({
        method: "POST",
        url: "/orders/missing-order/cancel",
        headers: { authorization: `Bearer ${other.token}` }
      });

      expect(paid.statusCode).toBe(409);
      expect(paid.json()).toEqual({
        message: "paid orders cannot be cancelled"
      });
      expect(notOwned.statusCode).toBe(404);
      expect(notOwned.json()).toEqual({ message: "order not found" });
      expect(missing.statusCode).toBe(404);
      expect(missing.json()).toEqual(notOwned.json());
      await expect(
        ownedContext.store.findOrderById(ownedContext.order.id)
      ).resolves.toMatchObject({ status: "PENDING" });
    });

    it("requires authentication, a valid route id, and an empty body", async () => {
      const context = await createCancellableOrderFixture();
      const unauthenticated = await context.server.inject({
        method: "POST",
        url: `/orders/${context.order.id}/cancel`
      });
      const invalidId = await context.server.inject({
        method: "POST",
        url: "/orders/bad.id/cancel",
        headers: { authorization: `Bearer ${context.token}` }
      });
      const suppliedStatus = await context.server.inject({
        method: "POST",
        url: `/orders/${context.order.id}/cancel`,
        headers: { authorization: `Bearer ${context.token}` },
        payload: { status: "CANCELLED" }
      });

      expect(unauthenticated.statusCode).toBe(401);
      expect(invalidId.statusCode).toBe(400);
      expect(invalidId.json()).toEqual({ message: "invalid order id" });
      expect(suppliedStatus.statusCode).toBe(400);
      expect(suppliedStatus.json()).toEqual({
        message: "request body must be empty"
      });
    });

    it("does not mutate PaymentAttempt evidence, quota, or credit events", async () => {
      const context = await createCancellableOrderFixture();
      await context.store.initializeInitialPaymentAttempt({
        orderId: context.order.id,
        provider: "epay",
        providerMerchantRef: "1001",
        paymentType: "alipay",
        merchantTradeNo: `order_${context.order.id}`,
        paymentUrl: "https://pay.example.test/submit.php"
      });
      const attemptBefore = await context.store.findPaymentAttemptByOrderAndOrdinal(
        context.order.id,
        INITIAL_PAYMENT_ATTEMPT_ORDINAL
      );
      const quotaBefore = await context.store.getQuota(context.user.id);
      const eventsBefore = context.store.getAccountCreditEventsForTest(
        context.user.id
      );

      const response = await context.server.inject({
        method: "POST",
        url: `/orders/${context.order.id}/cancel`,
        headers: { authorization: `Bearer ${context.token}` }
      });

      const attemptAfter = await context.store.findPaymentAttemptByOrderAndOrdinal(
        context.order.id,
        INITIAL_PAYMENT_ATTEMPT_ORDINAL
      );
      const quotaAfter = await context.store.getQuota(context.user.id);
      const eventsAfter = context.store.getAccountCreditEventsForTest(
        context.user.id
      );

      expect(response.statusCode).toBe(200);
      expect(attemptBefore).not.toBeNull();
      expect(attemptAfter).toEqual(attemptBefore);
      expect(attemptAfter).toMatchObject({
        status: "ACTIVE",
        providerTradeNo: null,
        providerTradeIdentityHash: null,
        paidAt: null
      });
      expect(quotaAfter).toEqual(quotaBefore);
      expect(eventsAfter).toEqual(eventsBefore);
    });
  });

