  it("keeps settings successful and logs a handled error when the best-effort audit write rejects", async () => {
    const store = createMemoryUserStore();
    const logCapture = createImageLogCapture();
    const configuredServer = createTestServer({
      store,
      logger: logCapture.logger
    });
    const admin = await registerAdminAndGetToken(configuredServer, store);
    const unhandledRejections: unknown[] = [];
    const onUnhandledRejection = (reason: unknown) => {
      unhandledRejections.push(reason);
    };
    const auditSpy = vi
      .spyOn(store, "createAuditLog")
      .mockRejectedValue(
        Object.assign(new Error("secret-setting-value"), { code: "P2000" })
      );

    process.on("unhandledRejection", onUnhandledRejection);
    try {
      const response = await configuredServer.inject({
        method: "PATCH",
        url: "/admin/settings",
        headers: {
          authorization: `Bearer ${admin.token}`,
          "content-type": "application/json"
        },
        payload: {
          settings: [
            { key: "siteName", value: "Audit survives", type: "string" }
          ]
        }
      });

      expect(response.statusCode).toBe(200);
      expect((await store.getSetting("siteName"))?.value).toBe("Audit survives");
      await flushImageLogCapture();
    } finally {
      process.removeListener("unhandledRejection", onUnhandledRejection);
      auditSpy.mockRestore();
    }

    expect(unhandledRejections).toEqual([]);
    const logText = logCapture.lines.join("\n");
    expect(logText).toContain("failed to write admin audit log");
    expect(logText).toContain("UPDATE_SITE_SETTINGS");
    expect(logText).toContain("P2000");
    expect(logText).not.toContain("secret-setting-value");
  });

