    it("persists one canonical message pair and one charge after sequential route fallback", async () => {
      const requestedModels: string[] = [];
      const fetchImpl = vi.fn<typeof fetch>(async (_url, init) => {
        const payload = JSON.parse(String(init?.body ?? "{}"));
        requestedModels.push(payload.model);

        if (payload.model === "route-one-model") {
          return new Response("temporarily unavailable", { status: 503 });
        }

        return new Response(
          JSON.stringify({
            model: payload.model,
            choices: [
              { message: { role: "assistant", content: "fallback once" } }
            ]
          }),
          { status: 200 }
        );
      });
      const { configuredServer, store } = await createTwoRouteChatServer(fetchImpl);
      const { token, user } = await registerAndGetToken(configuredServer);
      const claimInputs: Array<{ requestId: string; attemptIndex: number }> = [];
      const claimChatProviderAttempt = store.claimChatProviderAttempt.bind(store);
      vi.spyOn(store, "claimChatProviderAttempt").mockImplementation(async (input) => {
        claimInputs.push({
          requestId: input.requestId,
          attemptIndex: input.attemptIndex
        });
        return claimChatProviderAttempt(input);
      });

      const chatResult = await configuredServer.inject({
        method: "POST",
        url: "/chat/completions",
        headers: { authorization: `Bearer ${token}` },
        payload: {
          model: "gpt-test",
          messages: [{ role: "user", content: "fallback identity" }]
        }
      });
      const sessionId = chatResult.json().sessionId as string;
      const messages = await configuredServer.inject({
        method: "GET",
        url: `/chat/sessions/${sessionId}/messages`,
        headers: { authorization: `Bearer ${token}` }
      });
      const quota = await configuredServer.inject({
        method: "GET",
        url: "/quota/me",
        headers: { authorization: `Bearer ${token}` }
      });
      const usage = await configuredServer.inject({
        method: "GET",
        url: "/usage/me",
        headers: { authorization: `Bearer ${token}` }
      });

      expect(chatResult.statusCode).toBe(200);
      expect(requestedModels).toEqual(["route-one-model", "route-two-model"]);
      expect(messages.json().messages).toMatchObject([
        {
          role: "user",
          content: "fallback identity",
          model: "gpt-test"
        },
        {
          role: "assistant",
          content: "fallback once",
          model: "gpt-test"
        }
      ]);
      expect(messages.json().messages).toHaveLength(2);
      expect(quota.json().remainingCredits).toBe(19);
      expect(usage.json().logs).toHaveLength(2);
      expect(usage.json().logs[0]).toMatchObject({
        model: "gpt-test",
        canonicalModel: "gpt-test",
        upstreamModel: "route-two-model",
        fallbackAttempts: 1,
        status: "SUCCESS",
        costCredits: 1
      });
      expect(usage.json().logs[1]).toMatchObject({
        model: "gpt-test",
        status: "FAILED",
        costCredits: 0
      });
      expect(claimInputs).toHaveLength(2);
      expect(claimInputs[0]?.requestId).toBeTruthy();
      expect(claimInputs[1]?.requestId).toBe(claimInputs[0]?.requestId);
      expect(claimInputs.map((input) => input.attemptIndex)).toEqual([0, 1]);
      const creditEvents = store.getAccountCreditEventsForTest(user.id);
      const chatCharges = creditEvents.filter(
        (event) => event.sourceType === "CHAT_CHARGE"
      );
      const chatReleases = creditEvents.filter(
        (event) => event.sourceType === "CHAT_RELEASE"
      );
      expect(chatCharges).toHaveLength(1);
      expect(chatReleases).toHaveLength(0);
      expect(
        store.getCreditReservationForTest(chatCharges[0]!.sourceId)?.status
      ).toBe(CreditReservationStatus.SETTLED);
      expect(chatResult.body).not.toContain("CHAT_CHARGE");
      expect(chatResult.body).not.toContain(chatCharges[0]!.sourceId);
    });

