    it("tests Anthropic new-form provider accounts through the Messages API", async () => {
      const fetchImpl = vi.fn<typeof fetch>(async () => {
        return new Response(
          JSON.stringify({
            model: "claude-3-5-haiku-latest",
            content: [{ type: "text", text: "OK" }]
          }),
          { status: 200 }
        );
      });
      const store = createMemoryUserStore();
      const configuredServer = createTestServer({ store, fetchImpl });
      const logSpy = vi.spyOn(configuredServer.log, "info");
      const admin = await registerAdminAndGetToken(configuredServer, store);

      const result = await configuredServer.inject({
        method: "POST",
        url: "/admin/provider-accounts/test",
        headers: {
          authorization: `Bearer ${admin.token}`,
          "content-type": "application/json"
        },
        payload: {
          providerType: "ANTHROPIC",
          capabilities: ["chat"],
          baseUrl: "https://api.anthropic.com",
          apiKey: "sk-ant-test",
          headersJson: {},
          configJson: {
            testModel: "claude-3-5-haiku-latest",
            maxTokens: 512
          }
        }
      });

      expect(result.statusCode).toBe(200);
      expect(result.json()).toMatchObject({
        ok: true,
        providerType: "ANTHROPIC",
        requestFormat: "anthropic",
        authMode: "x-api-key",
        endpointPath: "/v1/messages",
        model: "claude-3-5-haiku-latest",
        message: "连接测试成功"
      });
      expect(fetchImpl).toHaveBeenCalledWith(
        "https://api.anthropic.com/v1/messages",
        expect.objectContaining({
          method: "POST"
        })
      );
      const headers = new Headers(fetchImpl.mock.calls[0]?.[1]?.headers);
      expect(headers.get("content-type")).toBe("application/json");
      expect(headers.get("x-api-key")).toBe("sk-ant-test");
      expect(headers.get("anthropic-version")).toBe("2023-06-01");
      expect(headers.get("authorization")).toBeNull();
      const body = JSON.parse(String(fetchImpl.mock.calls[0]?.[1]?.body));
      expect(body).toMatchObject({
        model: "claude-3-5-haiku-latest",
        max_tokens: 64,
        messages: [{ role: "user", content: "Reply with OK only." }]
      });
      expect(body).not.toHaveProperty("stream");
      const diagnosticCall = logSpy.mock.calls.find(
        (call) => call[1] === "provider-test Anthropic request summary"
      );
      expect(diagnosticCall?.[0]).toMatchObject({
        source: "provider-test",
        model: "claude-3-5-haiku-latest",
        messagesCount: 1,
        rolesSummary: "user:1",
        hasSystem: false,
        maxTokens: 64,
        temperature: 0,
        stream: false,
        endpointPath: "/v1/messages",
        requestFormat: "anthropic",
        anthropicAuthMode: "x-api-key",
        statusCode: 200
      });
      expect(JSON.stringify(logSpy.mock.calls)).not.toContain("sk-ant-test");
      expect(JSON.stringify(logSpy.mock.calls)).not.toContain(
        "Reply with OK only."
      );
    });

