    it("uses the stored exact route provider timeout without fallback", async () => {
      let signalAborted = false;
      const fetchImpl = vi.fn<typeof fetch>(async (_url, init) => {
        const signal = init?.signal;
        if (!signal) {
          return new Response("missing signal", { status: 500 });
        }

        return new Promise<Response>((_resolve, reject) => {
          const rejectAbort = () => {
            signalAborted = true;
            const error = new Error("provider request aborted");
            error.name = "AbortError";
            reject(error);
          };
          if (signal.aborted) {
            rejectAbort();
          } else {
            signal.addEventListener("abort", rejectAbort, { once: true });
          }
        });
      });
      const store = createMemoryUserStore();
      const provider = await store.createProviderAccount({
        name: "Exact Timeout Provider",
        providerType: "OPENAI_COMPATIBLE",
        baseUrl: "https://exact-timeout.example/v1",
        apiKey: "sk-exact-timeout",
        capabilities: ["chat"],
        enabled: true,
        timeoutMs: 300000
      });
      const fallbackProvider = await store.createProviderAccount({
        name: "Exact Timeout Fallback",
        providerType: "OPENAI_COMPATIBLE",
        baseUrl: "https://exact-timeout-fallback.example/v1",
        apiKey: "sk-exact-timeout-fallback",
        capabilities: ["chat"],
        enabled: true,
        timeoutMs: 60000
      });
      const route = await store.createModelRoute({
        modelId: "model_gpt_test",
        providerId: provider.id,
        upstreamModel: "exact-timeout-upstream",
        priority: 1,
        enabled: true
      });
      await store.createModelRoute({
        modelId: "model_gpt_test",
        providerId: fallbackProvider.id,
        upstreamModel: "must-not-fallback",
        priority: 2,
        enabled: true
      });
      const configuredServer = createTestServer({ store, fetchImpl });
      const admin = await registerAdminAndGetToken(configuredServer, store);

      vi.useFakeTimers();
      try {
        const resultPromise = configuredServer.inject({
          method: "POST",
          url: `/admin/model-routes/${route.id}/test`,
          headers: {
            authorization: `Bearer ${admin.token}`,
            "content-type": "application/json"
          },
          payload: {
            timeoutMs: 30000,
            upstreamModel: "client-timeout-and-model-must-be-ignored"
          }
        });

        await vi.advanceTimersByTimeAsync(59999);
        expect(signalAborted).toBe(false);
        await vi.advanceTimersByTimeAsync(1);
        const result = await resultPromise;

        expect(result.statusCode).toBe(502);
        expect(result.json()).toMatchObject({
          success: false,
          code: "ROUTE_TEST_TIMEOUT",
          errorCode: "ROUTE_TEST_TIMEOUT",
          upstreamModel: "exact-timeout-upstream",
          routeEnabled: true,
          providerEnabled: true
        });
        expect(result.json().code).not.toBe("ROUTE_TEST_REQUEST_FAILED");
        expect(signalAborted).toBe(true);
        expect(fetchImpl).toHaveBeenCalledTimes(1);
      } finally {
        vi.useRealTimers();
      }
    });

