  /**
   * Build a valid notify payload that will pass signature verification.
   * Uses the same EPAY_KEY as fullEpayEnv.
   */
  function buildValidNotifyPayload(
    overrides: Record<string, string> = {},
    merchantKey = "secret-merchant-key-123"
  ) {
    const base: Record<string, string> = {
      pid: "1001",
      trade_no: "TRADE20260614001",
      out_trade_no: "__will_be_overridden__",
      type: "alipay",
      name: "Starter",
      money: "29.00",
      trade_status: "TRADE_SUCCESS",
      sign_type: "MD5"
    };

    const merged = { ...base, ...overrides };

    // Only auto-compute the sign if it wasn't explicitly overridden
    if (!("sign" in overrides)) {
      const sign = signEpayParams(merged, merchantKey);
      merged.sign = sign;
    }

    return merged;
  }

  /**
   * Create a test setup with a PENDING order that has a paymentTradeNo set
   * (as if POST /orders/:id/pay was already called).
   */
  async function createNotifiableOrder(
    envOverrides: Record<string, string> = {},
    storeOverride?: MemoryServerStore
  ) {
    const ctx = await createPendingOrderWithAuth(envOverrides, storeOverride);

    // Call pay to set paymentTradeNo, paymentProvider etc.
    await ctx.server.inject({
      method: "POST",
      url: `/orders/${ctx.order.id}/pay`,
      headers: { authorization: `Bearer ${ctx.token}` }
    });

    // Re-read the order to get the updated paymentTradeNo
    const listRes = await ctx.server.inject({
      method: "GET",
      url: "/orders/me",
      headers: { authorization: `Bearer ${ctx.token}` }
    });
    const ordersList = (listRes.json() as { orders: OrderSummary[] }).orders;
    const updated = ordersList.find((o) => o.id === ctx.order.id)!;

    return { ...ctx, order: updated };
  }

  const callbackPaymentSettingsSecret =
    "callback-payment-settings-secret";
  const callbackDbPid = "db-callback-pid";
  const callbackDbKey = "db-callback-key";

  async function createDbNotifiableOrder() {
    const store = createMemoryUserStore();
    await store.upsertPaymentSetting("epay", {
      enabled: true,
      gatewayUrl: "https://db-epay.example.com/submit.php",
      pid: callbackDbPid,
      encryptedKey: encryptPaymentSecret(
        callbackDbKey,
        callbackPaymentSettingsSecret
      ),
      notifyUrl: fullEpayEnv.EPAY_NOTIFY_URL,
      returnUrl: fullEpayEnv.EPAY_RETURN_URL
    });

    return createNotifiableOrder(
      { PAYMENT_SETTINGS_SECRET: callbackPaymentSettingsSecret },
      store
    );
  }

