    it.each([
      ["missing file", "missing"],
      ["directory target", "directory"],
      ["symbolic-link target", "symlink"],
      ["size mismatch", "size-mismatch"]
    ])("returns a path-redacted 404 for %s", async (_label, scenario) => {
      const rootDir = await mkdtemp(
        resolve(tmpdir(), "s2-c1-b-file-error-")
      );
      const store = createMemoryUserStore();
      const srv = createTestServer({
        store,
        env: { GENERATED_ASSETS_DIR: rootDir }
      });

      try {
        const auth = await registerAndGetToken(srv);
        const assetId = "private-asset";
        const objectKey = "images/2026/07/private.png";
        const filePath = resolve(rootDir, objectKey);
        let expectedSizeBytes = privatePngBytes.byteLength;

        if (scenario === "directory") {
          await mkdir(filePath, { recursive: true });
        } else if (scenario === "symlink") {
          const targetPath = resolve(rootDir, "symlink-target.png");
          await mkdir(dirname(filePath), { recursive: true });
          await writeFile(targetPath, privatePngBytes);
          await symlink(targetPath, filePath);
        } else if (scenario === "size-mismatch") {
          await mkdir(dirname(filePath), { recursive: true });
          await writeFile(filePath, privatePngBytes);
          expectedSizeBytes += 1;
        }

        const storageObject = createStorageObject(auth.user.id, {
          objectKey,
          sizeBytes: expectedSizeBytes
        });
        configureContentRecords(
          store,
          {
            assetId,
            userId: auth.user.id,
            storageObjectId: storageObject.id
          },
          storageObject
        );
        const response = await srv.inject({
          method: "GET",
          url: `/assets/${assetId}/content`,
          headers: { authorization: `Bearer ${auth.token}` }
        });

        expect(response.statusCode).toBe(404);
        expect(response.json()).toEqual({ message: "asset not found" });
        expect(response.body).not.toContain(rootDir);
        expect(response.body).not.toContain(objectKey);
        expect(response.body).not.toContain("ENOENT");
        expect(response.body).not.toContain(storageObject.id);
      } finally {
        await srv.close();
        await rm(rootDir, { recursive: true, force: true });
      }
    });

