    it("re-resolves a delayed old moderation settings read before executing text moderation", async () => {
      const store = createMemoryUserStore();
      const account = await createModerationProviderAccount(
        store,
        "Delayed Moderation Settings Account"
      );
      await persistModerationCacheSettings(store, { enabled: true });
      await persistModerationSettings(store, [
        {
          id: "delayed-settings-route",
          providerAccountId: account.id,
          upstreamModel: "delayed-old-model",
          endpointPath: "/v1/moderations",
          priority: 1,
          enabled: true,
          timeoutMs: 3000,
          supportsText: true,
          supportsImage: true
        }
      ]);

      const textModels: string[] = [];
      const fetchImpl = vi.fn<typeof fetch>(async (_input, init) => {
        const body = JSON.parse(String(init?.body)) as {
          input?: Array<{ type?: string }>;
          model?: string;
        };
        if (body.input?.[0]?.type === "text") {
          textModels.push(body.model ?? "missing-model");
        }
        return safeModerationResponse();
      });
      const server = createTestServer({
        store,
        imageAdapter: createSuccessfulImageAdapter(),
        fetchImpl,
        moderationInputCacheSecret: "delayed-settings-read-secret",
        env: imageModerationEnv
      });
      const admin = await registerAdminAndGetToken(server, store);
      const { token } = await registerImageUser(server, store);
      await enableImageModel(store, 3);

      const warmedCache = await server.inject({
        method: "GET",
        url: "/admin/moderation/cache",
        headers: { authorization: `Bearer ${admin.token}` }
      });
      expect(warmedCache.statusCode).toBe(200);

      let markOldReadStarted!: () => void;
      const oldReadStarted = new Promise<void>((resolve) => {
        markOldReadStarted = resolve;
      });
      let releaseOldRead!: () => void;
      const oldReadGate = new Promise<void>((resolve) => {
        releaseOldRead = resolve;
      });
      const originalGetSetting = store.getSetting.bind(store);
      let delayOldRead = true;
      vi.spyOn(store, "getSetting").mockImplementation(async (key) => {
        const setting = await originalGetSetting(key);
        if (key === "imageModerationSettings" && delayOldRead) {
          delayOldRead = false;
          markOldReadStarted();
          await oldReadGate;
        }
        return setting;
      });

      const firstRequest = server.inject({
        method: "POST",
        url: "/image/generate",
        headers: { authorization: `Bearer ${token}` },
        payload: imagePayload
      });
      await oldReadStarted;

      const routeUpdate = await server.inject({
        method: "PUT",
        url: "/admin/moderation/routes/delayed-settings-route",
        headers: { authorization: `Bearer ${admin.token}` },
        payload: { upstreamModel: "delayed-new-model" }
      });
      expect(routeUpdate.statusCode).toBe(200);
      releaseOldRead();

      const firstResponse = await firstRequest;
      expect(firstResponse.statusCode).toBe(200);
      expect(textModels).toEqual(["delayed-new-model"]);

      const secondResponse = await server.inject({
        method: "POST",
        url: "/image/generate",
        headers: { authorization: `Bearer ${token}` },
        payload: imagePayload
      });
      expect(secondResponse.statusCode).toBe(200);
      expect(textModels).toEqual(["delayed-new-model"]);

      const cacheStatus = await server.inject({
        method: "GET",
        url: "/admin/moderation/cache",
        headers: { authorization: `Bearer ${admin.token}` }
      });
      expect(cacheStatus.statusCode).toBe(200);
      expect(cacheStatus.json().runtime.entries).toBe(1);
      expect(JSON.stringify(cacheStatus.json())).not.toContain(
        "delayed-old-model"
      );
    });

    it("retries when a route updates while text moderation is already in flight", async () => {
      const store = createMemoryUserStore();
      const account = await createModerationProviderAccount(
        store,
        "In Flight Route Update Account"
      );
      await persistModerationCacheSettings(store, { enabled: true });
      await persistModerationSettings(store, [
        {
          id: "in-flight-update-route",
          providerAccountId: account.id,
          upstreamModel: "in-flight-old-model",
          endpointPath: "/v1/moderations",
          priority: 1,
          enabled: true,
          timeoutMs: 3000,
          supportsText: true,
          supportsImage: true
        }
      ]);

      const textModels: string[] = [];
      let markTextStarted!: () => void;
      const textStarted = new Promise<void>((resolve) => {
        markTextStarted = resolve;
      });
      let releaseText!: () => void;
      const textGate = new Promise<void>((resolve) => {
        releaseText = resolve;
      });
      let textCallCount = 0;
      const fetchImpl = vi.fn<typeof fetch>(async (_input, init) => {
        const body = JSON.parse(String(init?.body)) as {
          input?: Array<{ type?: string }>;
          model?: string;
        };
        if (body.input?.[0]?.type === "text") {
          textModels.push(body.model ?? "missing-model");
          textCallCount += 1;
          if (textCallCount === 1) {
            markTextStarted();
            await textGate;
          }
        }
        return safeModerationResponse();
      });
      const imageAdapter = createSuccessfulImageAdapter();
      const server = createTestServer({
        store,
        imageAdapter,
        fetchImpl,
        moderationInputCacheSecret: "in-flight-route-update-secret",
        env: imageModerationEnv
      });
      const admin = await registerAdminAndGetToken(server, store);
      const { token } = await registerImageUser(server, store);
      await enableImageModel(store, 3);
      const warmedCache = await server.inject({
        method: "GET",
        url: "/admin/moderation/cache",
        headers: { authorization: `Bearer ${admin.token}` }
      });
      expect(warmedCache.statusCode).toBe(200);

      const firstRequest = server.inject({
        method: "POST",
        url: "/image/generate",
        headers: { authorization: `Bearer ${token}` },
        payload: imagePayload
      });
      await textStarted;

      const routeUpdate = await server.inject({
        method: "PUT",
        url: "/admin/moderation/routes/in-flight-update-route",
        headers: { authorization: `Bearer ${admin.token}` },
        payload: { upstreamModel: "in-flight-new-model" }
      });
      expect(routeUpdate.statusCode).toBe(200);
      releaseText();

      const firstResponse = await firstRequest;
      expect(firstResponse.statusCode).toBe(200);
      expect(textModels).toEqual([
        "in-flight-old-model",
        "in-flight-new-model"
      ]);
      expect(imageAdapter.createImageGeneration).toHaveBeenCalledTimes(1);

      const secondResponse = await server.inject({
        method: "POST",
        url: "/image/generate",
        headers: { authorization: `Bearer ${token}` },
        payload: imagePayload
      });
      expect(secondResponse.statusCode).toBe(200);
      expect(textModels).toEqual([
        "in-flight-old-model",
        "in-flight-new-model"
      ]);
      expect(imageAdapter.createImageGeneration).toHaveBeenCalledTimes(2);

      const cacheStatus = await server.inject({
        method: "GET",
        url: "/admin/moderation/cache",
        headers: { authorization: `Bearer ${admin.token}` }
      });
      expect(cacheStatus.statusCode).toBe(200);
      expect(cacheStatus.json().runtime.entries).toBe(1);
    });

