    it("audits four outputs in parallel and refunds two blocked outputs", async () => {
      const store = createMemoryUserStore();
      const services = createControlledRemoteImageServices(store);
      let releaseModeration: (() => void) | undefined;
      const gate = new Promise<void>((resolve) => {
        releaseModeration = resolve;
      });
      let active = 0;
      let maxActive = 0;
      const moderation = createImageModerationHarness(async ({ url }) => {
        active += 1;
        maxActive = Math.max(maxActive, active);
        await gate;
        active -= 1;
        return url.includes("blocked")
          ? { status: "blocked", categories: ["sexual"] }
          : { status: "allowed" };
      });
      const urls = [0, 1, 2, 3].map(
        (index) =>
          `https://cdn.example.com/moderation-${index % 2 ? "blocked" : "safe"}-${index}.png`
      );
      const imageAdapter = {
        createImageGeneration: vi.fn(async () => ({
          images: urls.map((url) => ({ sourceType: "url" as const, url }))
        }))
      };
      const server = createTestServer({
        store,
        imageAdapter,
        imageModerationClient: moderation.client,
        remoteImageFetcher: services.remoteImageFetcher,
        remoteImageStorageService: services.remoteImageStorageService,
        env: imageModerationEnv
      });
      const { token, user } = await registerImageUser(server, store);
      await enableImageModel(store, 3);
      const quotaBefore = (await store.getQuota(user.id)).remainingCredits;
      const responsePromise = server.inject({
        method: "POST",
        url: "/image/generate",
        headers: { authorization: `Bearer ${token}` },
        payload: { ...imagePayload, count: 4 }
      });

      for (let attempt = 0; attempt < 100 && moderation.moderateImage.mock.calls.length < 4; attempt += 1) {
        await new Promise<void>((resolve) => setImmediate(resolve));
      }
      expect(moderation.moderateImage).toHaveBeenCalledTimes(4);
      expect(maxActive).toBe(4);
      releaseModeration?.();
      const response = await responsePromise;

      expect(response.statusCode).toBe(200);
      expect(response.json().assets).toHaveLength(2);
      expect(services.fetchRemoteImage).toHaveBeenCalledTimes(2);
      expect(services.persistRemoteImage).toHaveBeenCalledTimes(2);
      expect((await store.getQuota(user.id)).remainingCredits).toBe(
        quotaBefore - 6
      );
    });

