        expect(budget.consumeGlobalBudget).toHaveBeenCalledTimes(0);
        expect(imageAdapter.createImageGeneration).toHaveBeenCalledTimes(0);
        expectSafeGlobalBudgetResponse(response.body, [
          invalidConfigMarker,
          "enforced",
          "13",
          "7",
          "2031-04-29",
          prompt,
          key,
          token
        ]);
