        const rateLimiter: RateLimiter = {
          async consume(key, policy) {
            if (key.startsWith("image:reference:user:")) {
              return {
                allowed: false,
                limit: policy.limit,
                remaining: 0,
                retryAfterMs: 2000
              };
            }
            return {
              allowed: true,
              limit: policy.limit,
              remaining: policy.limit - 1,
              retryAfterMs: policy.windowMs
            };
          },
          async close() {}
        };
        const srv = createTestServer({
          store,
          fetchImpl,
          rateLimiter,
          globalBudgetStore: budget.globalBudgetStore,
          globalBudgetNow: fixedGlobalBudgetNow,
          env: enforcedBudgetEnv
        });
