        const providerStarted = new Promise<void>((resolve) => {
          signalProviderStarted = resolve;
        });
        const providerResult = new Promise<{
          images: Array<{ sourceType: "url"; url: string }>;
        }>(
          (resolve) => {
            resolveProvider = resolve;
          }
        );
