    it("serializes concurrent same-key image requests and replays an identical success without a second provider or lease", async () => {
      const store = createMemoryUserStore();
      const lifecycle = trackImageLifecycle(store);
      const concurrency = createTrackingConcurrencyLimiter();
      let resolveProvider: ((value: {
        images: Array<{ sourceType: "url"; url: string }>;
      }) => void) | undefined;
      let signalProviderStarted: (() => void) | undefined;
      const providerStarted = new Promise<void>((resolve) => {
        signalProviderStarted = resolve;
      });
      const providerResult = new Promise<{
        images: Array<{ sourceType: "url"; url: string }>;
      }>(
        (resolve) => {
          resolveProvider = resolve;
        }
      );
      const imageAdapter = {
        createImageGeneration: vi.fn(() => {
          signalProviderStarted?.();
          return providerResult;
        })
      };
      const rateKeys: string[] = [];
      const srv = createTestServer({
        store,
        imageAdapter,
        concurrencyLimiter: concurrency.limiter,
        rateLimiter: {
          async consume(key, policy) {
            rateKeys.push(key);
            return {
              allowed: true,
              limit: policy.limit,
              remaining: policy.limit - 1,
              retryAfterMs: policy.windowMs
            };
          },
          async close() {}
        }
      });
      const { token, user } = await registerImageUser(srv, store);
      await enableImageModel(store, 3);
      const key = imageIdempotencyKey("concurrent");
      const headers = {
        authorization: `Bearer ${token}`,
        "idempotency-key": key
      };

      const firstPromise = srv.inject({
        method: "POST",
        url: "/image/generate",
        headers,
        payload: imagePayload
      });
      await providerStarted;
      const duplicate = await srv.inject({
        method: "POST",
        url: "/image/generate",
        headers,
        payload: imagePayload
      });

      expect(duplicate.statusCode).toBe(202);
      expect(duplicate.headers["retry-after"]).toBe("2");
      expect(duplicate.json()).toMatchObject({
        status: "in_progress",
        taskId: expect.any(String),
        retryAfterMs: 2000
      });
      expect(imageAdapter.createImageGeneration).toHaveBeenCalledTimes(1);
      expect(concurrency.acquire).toHaveBeenCalledTimes(1);

      resolveProvider?.({
        images: [{ sourceType: "url" as const, url: "https://cdn.example.com/idempotent.png" }]
      });
      const first = await firstPromise;
      const replay = await srv.inject({
        method: "POST",
        url: "/image/generate",
        headers,
        payload: imagePayload
      });

      expect(first.statusCode).toBe(200);
      expect(replay.statusCode).toBe(200);
      expect(replay.json()).toEqual(first.json());
      expect(imageAdapter.createImageGeneration).toHaveBeenCalledTimes(1);
      expect(lifecycle.create).toHaveBeenCalledTimes(1);
      expect(lifecycle.complete).toHaveBeenCalledTimes(1);
      expect(lifecycle.fail).not.toHaveBeenCalled();
      expect((await store.getQuota(user.id)).remainingCredits).toBe(17);
      expect(concurrency.acquire).toHaveBeenCalledTimes(1);
      expect(rateKeys.filter((value) => value === `image:generate:user:${user.id}`))
        .toHaveLength(3);
      expect(rateKeys.join("\n")).not.toContain(key);
      expect((await store.getQuota(user.id)).remainingCredits).toBe(17);
    });

