    it("terminalizes bound reference-limit, start, provider, invalid-output, and asset-persistence failures with one refund", async () => {
      const referenceStore = createMemoryUserStore();
      const referenceLifecycle = trackImageLifecycle(referenceStore);
      const referenceRateLimiter = {
        async consume(key: string, policy: { limit: number; windowMs: number }) {
          if (key.startsWith("image:reference:user:")) {
            return {
              allowed: false,
              limit: policy.limit,
              remaining: 0,
              retryAfterMs: 2000
            };
          }
          return {
            allowed: true,
            limit: policy.limit,
            remaining: policy.limit - 1,
            retryAfterMs: policy.windowMs
          };
        },
        async close() {}
      };
      const referenceServer = createTestServer({
        store: referenceStore,
        rateLimiter: referenceRateLimiter,
        fetchImpl: vi.fn()
      });
      const referenceUser = await registerImageUser(referenceServer, referenceStore);
      await bindAgnesImageProviderAccount(referenceStore);
      const referenceResponse = await referenceServer.inject({
        method: "POST",
        url: "/image/generate",
        headers: {
          authorization: `Bearer ${referenceUser.token}`,
          "idempotency-key": imageIdempotencyKey("reference-terminal")
        },
        payload: {
          ...imagePayload,
          mode: "image-to-image",
          referenceImage: {
            dataUrl: "data:image/png;base64,aW1hZ2U=",
            mimeType: "image/png"
          }
        }
      });
      expect(referenceResponse.statusCode).toBe(429);
      expect(referenceResponse.json()).toMatchObject({
        code: "REFERENCE_IMAGE_RATE_LIMITED"
      });
      expect(referenceLifecycle.markRunning).not.toHaveBeenCalled();
      expect(referenceLifecycle.fail).toHaveBeenCalledWith(
        expect.objectContaining({
          idempotencyTerminal: {
            responseStatus: 429,
            responseCode: "REFERENCE_IMAGE_RATE_LIMITED"
          }
        })
      );
      expect((await referenceStore.getQuota(referenceUser.user.id)).remainingCredits)
        .toBe(20);

      const cases = [
        {
          name: "task start",
          setup: (store: ReturnType<typeof createMemoryUserStore>) => {
            store.markAiTaskRunning = vi.fn(async () => null);
          },
          adapter: {
            createImageGeneration: vi.fn(async () => ({
              images: [{ sourceType: "url" as const, url: "https://cdn.example.com/not-called.png" }]
            }))
          },
          statusCode: 500,
          code: "IMAGE_TASK_START_FAILED"
        },
        {
          name: "provider",
          setup: () => {},
          adapter: {
            createImageGeneration: vi.fn(async () => {
              throw new Error("AI provider raw failure");
            })
          },
          statusCode: 502,
          code: "IMAGE_PROVIDER_FAILED"
        },
        {
          name: "invalid provider output",
          setup: () => {},
          adapter: {
            createImageGeneration: vi.fn(async () => ({ images: [] }))
          },
          statusCode: 502,
          code: "IMAGE_PROVIDER_INVALID_RESPONSE"
        }
      ] as const;

      for (const testCase of cases) {
        const store = createMemoryUserStore();
        testCase.setup(store);
        const lifecycle = trackImageLifecycle(store);
        const server = createTestServer({
          store,
          imageAdapter: testCase.adapter
        });
        const user = await registerImageUser(server, store);
        await enableImageModel(store, 3);
        const response = await server.inject({
          method: "POST",
          url: "/image/generate",
          headers: {
            authorization: `Bearer ${user.token}`,
            "idempotency-key": imageIdempotencyKey(
              testCase.name.replaceAll(" ", "-")
            )
          },
          payload: imagePayload
        });

        expect(response.statusCode).toBe(testCase.statusCode);
        expect(response.json()).toMatchObject({ code: testCase.code });
        expect(lifecycle.fail).toHaveBeenCalledTimes(1);
        expect(lifecycle.fail).toHaveBeenCalledWith(
          expect.objectContaining({
            idempotencyTerminal: {
              responseStatus: testCase.statusCode,
              responseCode: testCase.code
            }
          })
        );
        expect((await store.getQuota(user.user.id)).remainingCredits).toBe(20);
      }

      const assetStore = createMemoryUserStore();
      const assetLifecycle = trackImageLifecycle(assetStore);
      const assetServer = createTestServer({
        store: assetStore,
        env: { GENERATED_ASSETS_DIR: "/dev/null" },
        fetchImpl: vi.fn(async () => new Response(JSON.stringify({
          content: [{ type: "text", text: "![image](data:image/png;base64,iVBORw0KGgo=)" }]
        }), { status: 200 }))
      });
      const assetUser = await registerImageUser(assetServer, assetStore);
      await bindAnthropicImageProviderAccount(assetStore);
      const assetResponse = await assetServer.inject({
        method: "POST",
        url: "/image/generate",
        headers: {
          authorization: `Bearer ${assetUser.token}`,
          "idempotency-key": imageIdempotencyKey("asset-terminal")
        },
        payload: imagePayload
      });
      expect(assetResponse.statusCode).toBe(500);
      expect(assetResponse.json()).toMatchObject({
        code: "IMAGE_ASSET_PERSISTENCE_FAILED"
      });
      expect(assetLifecycle.fail).toHaveBeenCalledTimes(1);
      expect((await assetStore.getQuota(assetUser.user.id)).remainingCredits)
        .toBe(20);
    });

    it.each([
      ["throws", "THROW"],
      ["returns already completed", "ALREADY_COMPLETED"],
      ["returns an anomalous confirmation", "INVALID_STATE"]
    ] as const)(
      "rebuilds committed complete when acknowledgement %s",
      async (_label, acknowledgement) => {
        const store = createMemoryUserStore();
        const create = trackReservationCreation(store);
        const services = createControlledRemoteImageServices(store);
        const budget = createGlobalBudgetStore(async () => ({
          status: "consumed" as const
        }));
        const providerUrl =
          "https://cdn.example.com/private/native-image.png?token=TOP_SECRET";
        const originalComplete =
          store.completeImageTaskWithReservation.bind(store);
        const complete = vi.fn(async (input) => {
          const persisted = await originalComplete(input);
          expect(persisted.status).toBe("UPDATED");
          if (acknowledgement === "THROW") {
            throw new Error("complete acknowledgement lost");
          }
          return { status: acknowledgement };
        });
        store.completeImageTaskWithReservation = complete;
        const imageAdapter = {
          createImageGeneration: vi.fn(async () => ({
            images: [{ sourceType: "url" as const, url: providerUrl }]
          }))
        };
        const server = createTestServer({
          store,
          imageAdapter,
          remoteImageFetcher: services.remoteImageFetcher,
          remoteImageStorageService: services.remoteImageStorageService,
          globalBudgetStore: budget.globalBudgetStore,
          env: {
            GLOBAL_IMAGE_BUDGET_MODE: "enforced",
            GLOBAL_IMAGE_DAILY_BUDGET_CREDITS: "12",
            GLOBAL_IMAGE_MAX_REQUEST_COST_CREDITS: "3"
          }
        });
        const user = await registerImageUser(server, store);
        await enableImageModel(store, 3);
        const headers = {
          authorization: `Bearer ${user.token}`,
          "idempotency-key": imageIdempotencyKey(
            "complete-ack-" + acknowledgement.toLowerCase()
          )
        };

        const first = await server.inject({
          method: "POST",
          url: "/image/generate",
          headers,
          payload: imagePayload
        });
        const replay = await server.inject({
          method: "POST",
          url: "/image/generate",
          headers,
          payload: imagePayload
        });

        expect(first.statusCode).toBe(200);
        expect(replay.statusCode).toBe(200);
        const firstBody = first.json() as {
          task: AiTaskSummary;
          assets: AiAssetSummary[];
        };
        const replayBody = replay.json();
        expect(firstBody.task.status).toBe("succeeded");
        await expectPrivateNativeAssets({
          store,
          userId: user.user.id,
          task: firstBody.task,
          assets: firstBody.assets,
          providerUrls: [providerUrl]
        });
        expect(replayBody).toEqual(firstBody);
        for (const response of [first, replay]) {
          expectNoProviderUrlLeak(response.json(), providerUrl);
          expect(response.body).not.toContain("/private/native-image.png");
          expect(response.body).not.toContain("token=TOP_SECRET");
          expect(response.body).not.toContain("cdn.example.com");
        }
        const created = await create.mock.results[0]?.value;
        if (!created?.ok) {
          throw new Error("EXPECTED_COMPLETE_ACK_RESERVATION");
        }
        expect(complete).toHaveBeenCalledTimes(1);
        expect(imageAdapter.createImageGeneration).toHaveBeenCalledTimes(1);
        expect(services.fetchRemoteImage).toHaveBeenCalledTimes(1);
        expect(services.persistRemoteImage).toHaveBeenCalledTimes(1);
        expect(budget.consumeGlobalBudget).toHaveBeenCalledTimes(1);
        expect(
          store.getCreditReservationForTest(created.reservation.id)
        ).toMatchObject({
          status: CreditReservationStatus.SETTLED,
          releasedAt: null
        });
        expect(
          await readImageIdempotencyState(
            store,
            user.user.id,
            headers["idempotency-key"]
          )
        ).toMatchObject({ status: "SUCCEEDED", responseStatus: 200 });
        expect((await store.getQuota(user.user.id)).remainingCredits).toBe(17);
      }
    );

