    it("keeps persistence catches isolated from response sends", () => {
      const source = readFileSync(resolve(process.cwd(), "src/server.ts"), "utf8");
      const successHelper = source.slice(
        source.indexOf("async function sendIdempotencySucceededReplay"),
        source.indexOf("function sendIdempotencyFailedReplay")
      );
      const successPersistenceBlock = successHelper.slice(
        successHelper.indexOf("let detail:"),
        successHelper.indexOf("if (readFailed)")
      );
      const failHelper = source.slice(
        source.indexOf("const failBoundImageTask"),
        source.indexOf("let created;", source.indexOf("const failBoundImageTask"))
      );
      const failPersistenceBlock = failHelper.slice(
        failHelper.indexOf("let failed:"),
        failHelper.indexOf("if (failureMutationThrew)")
      );

      expect(successPersistenceBlock).toContain(
        "detail = await store.findAiTaskForUser"
      );
      expect(successPersistenceBlock).not.toContain(".send(");
      expect(successPersistenceBlock).not.toContain("sendImageGenerationFailure");
      expect(failPersistenceBlock).toContain(
        "failed = await store.failImageTaskAndReleaseReservation"
      );
      expect(failPersistenceBlock).not.toContain(".send(");
      expect(failPersistenceBlock).not.toContain("sendImageGenerationFailure");
      expect(successHelper + failHelper).not.toContain("reply.sent");
    });

