    it("returns a structured retryable image rate-limit failure", async () => {
      const store = createMemoryUserStore();
      const imageAdapter = { createImageGeneration: vi.fn() };
      const srv = createTestServer({
        store,
        imageAdapter,
        defaultImageIdempotencyKey: false,
        rateLimiter: {
          async consume(key, policy) {
            if (key.startsWith("image:generate:user:")) {
              return {
                allowed: false,
                limit: policy.limit,
                remaining: 0,
                retryAfterMs: 2500
              };
            }
            return {
              allowed: true,
              limit: policy.limit,
              remaining: policy.limit - 1,
              retryAfterMs: policy.windowMs
            };
          },
          async close() {}
        }
      });
      const { token, user } = await registerImageUser(srv, store);

      const response = await srv.inject({
        method: "POST",
        url: "/image/generate",
        headers: {
          authorization: `Bearer ${token}`,
          "idempotency-key": imageIdempotencyKey("user-rate-limited")
        },
        payload: imagePayload
      });

      expect(response.statusCode).toBe(429);
      expect(response.headers["retry-after"]).toBe("3");
      expect(response.json()).toEqual({
        code: "IMAGE_RATE_LIMITED",
        message: "请求过于频繁，请稍后再试",
        retryAfterSeconds: 3,
        retryable: true
      });
      expect(imageAdapter.createImageGeneration).not.toHaveBeenCalled();
      expect(await store.listAiTasksForUser(user.id)).toHaveLength(0);
    });

