      it.each([
        {
          label: "401 auth failure",
          error: new AIProviderRequestError("raw upstream 401 body", {
            statusCode: 401,
            endpointPath: "/images/generations"
          }),
          reasonCode: "PROVIDER_AUTH_FAILED"
        },
        {
          label: "429 rate limit",
          error: new AIProviderRequestError("raw upstream 429 body", {
            statusCode: 429,
            endpointPath: "/images/generations"
          }),
          reasonCode: "PROVIDER_RATE_LIMITED"
        },
        {
          label: "503 upstream failure",
          error: new AIProviderRequestError("raw upstream 503 body", {
            statusCode: 503,
            endpointPath: "/images/generations"
          }),
          reasonCode: "PROVIDER_UPSTREAM_FAILED"
        },
        {
          label: "provider timeout",
          error: new AIProviderTimeoutError(),
          reasonCode: "PROVIDER_TIMEOUT"
        },
        {
          label: "invalid response",
          error: new AIProviderResponseFormatError(),
          reasonCode: "PROVIDER_INVALID_RESPONSE"
        }
      ] as const)(
        "classifies $label without persistence taxonomy or sensitive logs",
        async ({ error, reasonCode }) => {
          const capture = createImageLogCapture();
          const store = createMemoryUserStore();
          const imageAdapter = {
            createImageGeneration: vi.fn(async () => {
              throw error;
            })
          };
          const srv = createTestServer({ store, imageAdapter, logger: capture.logger });
          const { token } = await registerImageUser(srv, store);
          await enableImageModel(store, 1);

          try {
            const response = await srv.inject({
              method: "POST",
              url: "/image/generate",
              headers: { authorization: `Bearer ${token}` },
              payload: {
                ...imagePayload,
                prompt: "P05_PROVIDER_DIAGNOSTIC_PROMPT"
              }
            });
            await flushImageLogCapture();

            expect(response.statusCode).toBe(
              reasonCode === "PROVIDER_TIMEOUT" ? 504 : 502
            );
            expect(response.body).not.toContain("raw upstream");
            const records = capture.lines.map(
              (line) => JSON.parse(line) as Record<string, unknown>
            );
            const record = records.find(
              (candidate) => candidate.msg === "image generation failed"
            );
            expect(record).toMatchObject({
              reasonCode,
              stage:
                reasonCode === "PROVIDER_INVALID_RESPONSE"
                  ? "provider-output"
                  : "provider-request",
              attemptIndex: 0,
              endpointPath: "/images/generations",
              willFallback: false,
              providerAttemptDurationMs: expect.any(Number),
              durationMs: expect.any(Number)
            });
            expect(capture.lines.join(""))
              .not.toContain("P05_PROVIDER_DIAGNOSTIC_PROMPT");
            expect(capture.lines.join("")).not.toContain("raw upstream");
          } finally {
            await srv.close();
          }
        }
      );

