    it("allows native-image image-to-image for OpenAI-compatible providers", async () => {
      const store = createMemoryUserStore();
      const local = createTestAvatarStorageObjectService(store);
      const fetchImpl = vi.fn<typeof fetch>(async () =>
        new Response(
          JSON.stringify({
            data: [{ b64_json: "iVBORw0KGgo=" }]
          }),
          { status: 200, headers: { "content-type": "application/json" } }
        )
      );
      const srv = createTestServer({
        store,
        fetchImpl,
        avatarStorageObjectService: local.service
      });
      const { token, user } = await registerImageUser(srv, store);
      await bindOpenAIImageProviderAccount(store, {
        configJson: { imageResponseFormat: "b64_json" }
      });
      const referenceImage = {
        dataUrl: "data:image/png;base64,aW1hZ2U=",
        mimeType: "image/png",
        name: "../../must-not-be-used-as-a-file-name"
      };

      const res = await srv.inject({
        method: "POST",
        url: "/image/generate",
        headers: { authorization: `Bearer ${token}` },
        payload: {
          prompt: "Restyle this room",
          modelId: "expensive-test",
          size: "1024x1024",
          count: 1,
          mode: "image-to-image",
          referenceImage
        }
      });

      expect(res.statusCode).toBe(200);
      const editCalls = fetchImpl.mock.calls.filter(([input]) =>
        String(input).endsWith("/images/edits")
      );
      expect(editCalls).toHaveLength(1);
      expect(fetchImpl.mock.calls.some(([input]) =>
        String(input).endsWith("/images/generations")
      )).toBe(false);
      const [url, init] = editCalls[0] ?? [];
      expect(url).toBe(
        "https://openai-compatible.example/v1/images/edits"
      );
      expect(init?.method).toBe("POST");
      const rawHeaders = new Headers(init?.headers);
      expect(rawHeaders.get("content-type")).toBeNull();
      const headers = new Request(String(url), init).headers;
      expect(headers.get("content-type")).toMatch(
        /^multipart\/form-data; boundary=/u
      );
      expect(headers.get("content-type")).not.toBe("application/json");
      expect(headers.get("authorization")).toBe(
        "Bearer openai-image-secret"
      );
      const form = init?.body;
      expect(form).toBeInstanceOf(FormData);
      if (!(form instanceof FormData)) {
        throw new Error("EXPECTED_API_OPENAI_EDIT_FORM_DATA");
      }
      expect(form.get("model")).toBe("expensive-test");
      expect(form.get("prompt")).toBe("Restyle this room");
      expect(form.get("size")).toBe("1024x1024");
      expect(form.get("n")).toBe("1");
      expect(form.get("response_format")).toBe("b64_json");
      const uploadedImage = form.get("image");
      if (uploadedImage === null || typeof uploadedImage === "string") {
        throw new Error("EXPECTED_API_OPENAI_EDIT_IMAGE_UPLOAD");
      }
      expect(uploadedImage.name).toBe("reference.png");
      expect(uploadedImage.type).toBe("image/png");
      expect(new Uint8Array(await uploadedImage.arrayBuffer())).toEqual(
        new Uint8Array([105, 109, 97, 103, 101])
      );

      const body = res.json() as {
        task: AiTaskSummary;
        assets: AiAssetSummary[];
      };
      expect(body.task.status).toBe("succeeded");
      expect(body.task.input).toMatchObject({
        mode: "image-to-image",
        referenceImage: {
          mimeType: "image/png",
          name: "../../must-not-be-used-as-a-file-name"
        }
      });
      expect(JSON.stringify(body.task.input)).not.toContain(
        referenceImage.dataUrl
      );
      expect(JSON.stringify(body.task.input)).not.toContain("aW1hZ2U=");
      expect(body.assets).toHaveLength(1);
      expect(local.persist).toHaveBeenCalledTimes(1);
      expect((await store.getQuota(user.id)).remainingCredits).toBe(17);
    });

