    it("validates reference image Data URLs before the adapter and reference bucket", async () => {
      const store = createMemoryUserStore();
      const fetchImpl = vi.fn<typeof fetch>(async () =>
        new Response(
          JSON.stringify({
            data: [{ url: "https://agnes-cdn.example.com/validated.png" }]
          }),
          { status: 200 }
        )
      );
      const keys: string[] = [];
      const srv = createTestServer({
        store,
        fetchImpl,
        rateLimiter: {
          async consume(key, policy) {
            keys.push(key);
            return {
              allowed: true,
              limit: policy.limit,
              remaining: policy.limit - 1,
              retryAfterMs: policy.windowMs
            };
          },
          async close() {}
        }
      });
      const { token } = await registerImageUser(srv, store);
      await bindAgnesImageProviderAccount(store);
      await enableImageModel(store);
      const basePayload = {
        prompt: "Restyle this room",
        modelId: "expensive-test",
        size: "1024x1024",
        count: 1,
        mode: "image-to-image"
      } as const;
      const validImages = [
        { dataUrl: "data:image/jpeg;base64,/9j/", mimeType: "image/jpeg" },
        { dataUrl: "data:image/png;base64,iVBORw0KGgo=", mimeType: "image/png" },
        { dataUrl: "data:image/webp;base64,UklGRg==", mimeType: "image/webp" }
      ];

      for (const referenceImage of validImages) {
        const response = await srv.inject({
          method: "POST",
          url: "/image/generate",
          headers: { authorization: `Bearer ${token}` },
          payload: { ...basePayload, referenceImage }
        });
        expect(response.statusCode).toBe(200);
      }

      const invalidResponses = await Promise.all([
        srv.inject({
          method: "POST",
          url: "/image/generate",
          headers: { authorization: `Bearer ${token}` },
          payload: {
            ...basePayload,
            referenceImage: {
              dataUrl: "data:image/svg+xml;base64,PHN2Zz4=",
              mimeType: "image/svg+xml"
            }
          }
        }),
        srv.inject({
          method: "POST",
          url: "/image/generate",
          headers: { authorization: `Bearer ${token}` },
          payload: {
            ...basePayload,
            referenceImage: {
              dataUrl: "data:image/gif;base64,R0lGODlh",
              mimeType: "image/gif"
            }
          }
        }),
        srv.inject({
          method: "POST",
          url: "/image/generate",
          headers: { authorization: `Bearer ${token}` },
          payload: {
            ...basePayload,
            referenceImage: {
              dataUrl: "data:application/octet-stream;base64,aW1hZ2U=",
              mimeType: "application/octet-stream"
            }
          }
        }),
        srv.inject({
          method: "POST",
          url: "/image/generate",
          headers: { authorization: `Bearer ${token}` },
          payload: {
            ...basePayload,
            referenceImage: {
              dataUrl: "data:image/png;base64,",
              mimeType: "image/png"
            }
          }
        }),
        srv.inject({
          method: "POST",
          url: "/image/generate",
          headers: { authorization: `Bearer ${token}` },
          payload: {
            ...basePayload,
            referenceImage: {
              dataUrl: "data:image/png;base64,not-base64!",
              mimeType: "image/png"
            }
          }
        })
      ]);

      for (const response of invalidResponses) {
        expect(response.statusCode).toBe(400);
        expect(response.json()).toEqual({
          code: "REFERENCE_IMAGE_INVALID",
          message: "参考图片格式不受支持",
          retryable: false
        });
      }

      const tooMany = await srv.inject({
        method: "POST",
        url: "/image/generate",
        headers: { authorization: `Bearer ${token}` },
        payload: {
          ...basePayload,
          referenceImages: Array.from({ length: 5 }, () => validImages[0])
        }
      });

      expect(tooMany.statusCode).toBe(400);
      expect(tooMany.json()).toEqual({
        code: "REFERENCE_IMAGE_COUNT_EXCEEDED",
        message: "参考图片数量超过限制",
        retryable: false
      });
      expect(keys.filter((key) => key.startsWith("image:reference:user:")).length).toBe(3);
      expect(fetchImpl).toHaveBeenCalledTimes(3);
    });

    it("uses decoded byte limits and rejects total reference payloads", async () => {
      const store = createMemoryUserStore();
      const imageAdapter = {
        createImageGeneration: vi.fn(async () => ({
          images: [{ sourceType: "url" as const, url: "https://generated.example/image.png" }]
        }))
      };
      const srv = createTestServer({ store, imageAdapter });
      const { token } = await registerImageUser(srv, store);
      const dataUrlForBytes = (bytes: number) =>
        `data:image/png;base64,${Buffer.alloc(bytes, 1).toString("base64")}`;
      const basePayload = {
        prompt: "Restyle this room",
        modelId: "expensive-test",
        size: "1024x1024",
        count: 1,
        mode: "image-to-image"
      } as const;

      const singleTooLarge = await srv.inject({
        method: "POST",
        url: "/image/generate",
        headers: { authorization: `Bearer ${token}` },
        payload: {
          ...basePayload,
          referenceImage: {
            dataUrl: dataUrlForBytes(5 * 1024 * 1024 + 1),
            mimeType: "image/png"
          }
        }
      });
      expect(singleTooLarge.statusCode).toBe(413);
      expect(singleTooLarge.json()).toEqual({
        code: "REFERENCE_IMAGE_TOO_LARGE",
        message: "单张参考图片超过大小限制",
        retryable: false
      });

      const totalTooLarge = await srv.inject({
        method: "POST",
        url: "/image/generate",
        headers: { authorization: `Bearer ${token}` },
        payload: {
          ...basePayload,
          referenceImages: [
            { dataUrl: dataUrlForBytes(5 * 1024 * 1024), mimeType: "image/png" },
            { dataUrl: dataUrlForBytes(5 * 1024 * 1024), mimeType: "image/png" },
            { dataUrl: dataUrlForBytes(1), mimeType: "image/png" }
          ]
        }
      });
      expect(totalTooLarge.statusCode).toBe(413);
      expect(totalTooLarge.json()).toEqual({
        code: "REFERENCE_IMAGES_TOTAL_TOO_LARGE",
        message: "参考图片总大小超过限制",
        retryable: false
      });
      expect(imageAdapter.createImageGeneration).not.toHaveBeenCalled();
    });

