    it("replays ordered multi-reference requests and conflicts on reversed order without raw idempotency input", async () => {
      const store = createMemoryUserStore();
      const imageAdapter = createSuccessfulImageAdapter();
      const claim = vi.fn(store.claimIdempotencyRequest.bind(store));
      store.claimIdempotencyRequest = claim;
      const srv = createTestServer({
        store,
        imageAdapter,
        defaultImageIdempotencyKey: false
      });
      const { token } = await registerImageUser(srv, store);
      await enableImageModel(store, 3, 4);
      const key = imageIdempotencyKey("ordered-multi-ref");
      const headers = {
        authorization: `Bearer ${token}`,
        "idempotency-key": key
      };
      const referenceImages = [
        { dataUrl: "data:image/png;base64,AQID", mimeType: "image/png" },
        { dataUrl: "data:image/jpeg;base64,BAUG", mimeType: "image/jpeg" }
      ] as const;
      const payload = {
        prompt: "Ordered idempotency",
        modelId: "expensive-test",
        size: "1024x1024",
        count: 1,
        mode: "image-to-image",
        referenceImages
      } as const;

      const first = await srv.inject({
        method: "POST",
        url: "/image/generate",
        headers,
        payload
      });
      const replay = await srv.inject({
        method: "POST",
        url: "/image/generate",
        headers,
        payload
      });
      const reversed = await srv.inject({
        method: "POST",
        url: "/image/generate",
        headers,
        payload: { ...payload, referenceImages: [...referenceImages].reverse() }
      });

      expect(first.statusCode).toBe(200);
      expect(replay.statusCode).toBe(200);
      expect(replay.json()).toEqual(first.json());
      expect(reversed.statusCode).toBe(409);
      expect(reversed.json()).toEqual({
        message: "该 Idempotency-Key 已用于不同的请求",
        code: "IDEMPOTENCY_KEY_CONFLICT",
        retryable: false
      });
      expect(imageAdapter.createImageGeneration).toHaveBeenCalledTimes(1);
      const claimInputs = JSON.stringify(claim.mock.calls);
      for (const referenceImage of referenceImages) {
        expect(claimInputs).not.toContain(referenceImage.dataUrl);
      }
    });

