    it("keeps Agnes batch completion idempotent after a partial success", async () => {
      const store = createMemoryUserStore();
      const services = createControlledRemoteImageServices(store);
      const providerUrl = "https://agnes-cdn.example.com/partial.png";
      const fetchImpl = vi.fn<typeof fetch>(async () => {
        if (fetchImpl.mock.calls.length === 3) {
          return new Response("Agnes later candidate failed", { status: 503 });
        }
        return new Response(
          JSON.stringify({ data: [{ url: providerUrl }] }),
          { status: 200 }
        );
      });
      const srv = createTestServer({
        store,
        fetchImpl,
        remoteImageFetcher: services.remoteImageFetcher,
        remoteImageStorageService: services.remoteImageStorageService
      });
      const { token, user } = await registerImageUser(srv, store);
      await bindAgnesImageProviderAccount(store, {
        apiKey: "agnes-count-secret",
        baseUrl: "https://agnes.example/api"
      });
      const headers = {
        authorization: `Bearer ${token}`,
        "idempotency-key": imageIdempotencyKey("agnes-count-four")
      };
      const payload = {
        prompt: "A single Agnes result",
        modelId: "expensive-test",
        size: "1024x1024",
        count: 4 as const
      };

      const first = await srv.inject({
        method: "POST",
        url: "/image/generate",
        headers,
        payload
      });
      const replay = await srv.inject({
        method: "POST",
        url: "/image/generate",
        headers,
        payload
      });
      const body = first.json() as {
        task: AiTaskSummary;
        assets: AiAssetSummary[];
      };
      const events = store.getAccountCreditEventsForTest(user.id);

      expect(first.statusCode).toBe(200);
      expect(replay.statusCode).toBe(200);
      expect(replay.json()).toEqual(body);
      expect(fetchImpl).toHaveBeenCalledTimes(3);
      expect(body.task).toMatchObject({
        status: "succeeded",
        costCredits: 6,
        input: { count: 4 }
      });
      expect(body.assets).toHaveLength(2);
      expect(events.filter((event) => event.sourceType === "IMAGE_CHARGE"))
        .toHaveLength(1);
      expect(events.filter((event) => event.sourceType === "IMAGE_RELEASE"))
        .toHaveLength(1);
      expect(events.find((event) => event.sourceType === "IMAGE_CHARGE"))
        .toMatchObject({ deltaCredits: -12 });
      expect(events.find((event) => event.sourceType === "IMAGE_RELEASE"))
        .toMatchObject({ deltaCredits: 6 });
      expect((await store.getQuota(user.id)).remainingCredits).toBe(14);
      expect(services.fetchRemoteImage).toHaveBeenCalledTimes(2);
      expect(services.persistRemoteImage).toHaveBeenCalledTimes(2);
    });

