    it("clears the image provider timer after a successful generation", async () => {
      const store = createMemoryUserStore();
      const lifecycle = trackImageLifecycle(store);
      let providerSignal: AbortSignal | undefined;
      const imageAdapter = {
        createImageGeneration: vi.fn(async (input: { signal?: AbortSignal }) => {
          providerSignal = input.signal;
          return { images: [{ sourceType: "url" as const, url: "https://cdn.example.com/timer-clean.png" }] };
        })
      };
      const srv = createTestServer({ store, imageAdapter });
      const { token } = await registerImageUser(srv, store);
      const providerTimeoutMs = 1234;
      await bindOpenAIImageProviderAccount(store, {
        timeoutMs: providerTimeoutMs
      });

      const setTimeoutSpy = vi.spyOn(globalThis, "setTimeout");
      const clearTimeoutSpy = vi.spyOn(globalThis, "clearTimeout");
      try {
        const response = await srv.inject({
          method: "POST",
          url: "/image/generate",
          headers: { authorization: `Bearer ${token}` },
          payload: {
            prompt: "A successful image",
            modelId: "expensive-test",
            size: "1024x1024",
            count: 1
          }
        });

        expect(response.statusCode).toBe(200);
        expect(lifecycle.complete).toHaveBeenCalledTimes(1);
        expect(lifecycle.fail).not.toHaveBeenCalled();

        const providerTimeoutCallIndex = setTimeoutSpy.mock.calls.findIndex(
          ([, delay]) => delay === providerTimeoutMs
        );
        expect(providerTimeoutCallIndex).toBeGreaterThanOrEqual(0);

        if (providerTimeoutCallIndex < 0) {
          throw new Error("provider timeout timer was not scheduled");
        }

        const providerTimeoutHandle =
          setTimeoutSpy.mock.results[providerTimeoutCallIndex]?.value;
        if (providerTimeoutHandle === undefined) {
          throw new Error("provider timeout timer handle was not returned");
        }

        expect(clearTimeoutSpy).toHaveBeenCalledWith(providerTimeoutHandle);
        expect(providerSignal?.aborted).toBe(false);
      } finally {
        clearTimeoutSpy.mockRestore();
        setTimeoutSpy.mockRestore();
      }
    });

