    it("does not fallback after a streaming delta when the client aborts", async () => {
      const store = createMemoryUserStore();
      const complete = vi.spyOn(store, "completeChatProviderAttempt");
      const requestedModels: string[] = [];
      let upstreamSignal: AbortSignal | undefined;
      const deltaSent = createBarrier<void>();
      let clientRequest: ReturnType<typeof httpRequest> | null = null;
      const fetchImpl = vi.fn<typeof fetch>(async (_url, init) => {
        const payload = JSON.parse(String(init?.body ?? "{}")) as {
          model?: string;
        };
        requestedModels.push(payload.model ?? "");
        upstreamSignal = init?.signal ?? undefined;
        if (payload.model === "route-1-model") {
          return createDeltaThenPendingResponse("partial client output", () => {
            deltaSent.resolve(undefined);
            setImmediate(() => clientRequest?.destroy());
          }, init?.signal ?? undefined);
        }
        return createHardeningStreamingResponse("must not reach second route");
      });
      const budget = createHardeningBudgetStore(async () => ({
        status: "consumed" as const
      }));
      const srv = createHardeningServer({
        store,
        fetchImpl,
        globalBudgetStore: budget.globalBudgetStore
      });
      const admin = await registerAdminAndGetToken(srv, store);
      await configureHardeningChatRoutes(srv, admin.token);
      const port = await listenOnLoopback(srv);

      try {
        clientRequest = httpRequest(
          {
            hostname: "127.0.0.1",
            port,
            path: "/chat/completions/stream",
            method: "POST",
            headers: {
              authorization: `Bearer ${admin.token}`,
              "content-type": "application/json"
            }
          },
          (response) => {
            response.resume();
          }
        );
        clientRequest.on("error", () => {});
        clientRequest.end(
          JSON.stringify({
            model: "gpt-test",
            messages: [{ role: "user", content: "partial then disconnect" }]
          })
        );

        await deltaSent.promise;
        await vi.waitFor(
          () => {
            expect(upstreamSignal?.aborted).toBe(true);
            expect(complete).toHaveBeenCalledWith(
              expect.objectContaining({
                requestId: expect.any(String),
                attemptIndex: 0,
                status: "ABORTED"
              })
            );
          },
          { timeout: 1_000, interval: 10 }
        );
        expect(fetchImpl).toHaveBeenCalledTimes(1);
        expect(requestedModels).toEqual(["route-1-model"]);
      } finally {
        await srv.close();
      }
    });

